1	// Cold Email Engine — reply classification (Overhaul Phase 1).
2	//
3	// Two layers, both here:
4	//   1. PURE rule-based detection (no I/O) — catches unsubscribe / opt-out phrasing,
5	//      out-of-office, and automated bounces/auto-replies. Runs ALWAYS, so an
6	//      unsubscribe is honoured even with no Anthropic key configured. The tests
7	//      exercise this + the class→status/stage mapping directly.
8	//   2. An OPTIONAL AI refinement (askClaude) into interested / not-interested. It
9	//      only ever UPGRADES a reply the rules left ambiguous; it can never override a
10	//      rule-detected unsubscribe. Degrades gracefully to null with no API key.
11	//
12	// The five buckets mirror the ConversationStatus reply values.
13	
14	import { askClaude, effectiveKeyFor, type ClaudeMessage } from "@/lib/anthropic";
15	
16	export type ReplyClass = "INTERESTED" | "NOT_INTERESTED" | "AUTO_REPLY" | "OUT_OF_OFFICE" | "UNSUBSCRIBE";
17	
18	// Prisma enum string unions (kept as literals so this module stays free of the
19	// generated client — it must be importable in a DB-less test).
20	export type ConversationStatusValue =
21	  | "OPEN"
22	  | "REPLIED"
23	  | "INTERESTED"
24	  | "NOT_INTERESTED"
25	  | "AUTO_REPLY"
26	  | "OUT_OF_OFFICE"
27	  | "UNSUBSCRIBE"
28	  | "CLOSED";
29	
30	export type ContactStageValue =
31	  | "NEW"
32	  | "CONTACTED"
33	  | "REPLIED"
34	  | "INTERESTED"
35	  | "MEETING_BOOKED"
36	  | "WON"
37	  | "LOST";
38	
39	// ---------------------------------------------------------------------------
40	// PURE rule-based detection
41	// ---------------------------------------------------------------------------
42	
43	const UNSUB_PATTERNS: RegExp[] = [
44	  /\bunsubscribe\b/i,
45	  /\bopt[\s-]?out\b/i,
46	  /\bremove me\b/i,
47	  /\btake me off\b/i,
48	  /\bstop (?:emailing|contacting|messaging) me\b/i,
49	  /\bdo not (?:contact|email|reach out)\b/i,
50	  /\bdon'?t (?:contact|email) me\b/i,
51	  /\bno longer (?:wish|want) to (?:receive|hear)\b/i,
52	];
53	
54	const OOO_PATTERNS: RegExp[] = [
55	  /\bout of (?:the )?office\b/i,
56	  /\bon (?:vacation|holiday|annual leave|parental leave|maternity leave)\b/i,
57	  /\baway from my (?:desk|email)\b/i,
58	  /\bwill be (?:back|returning) on\b/i,
59	  /\blimited access to (?:my )?email\b/i,
60	];
61	
62	const AUTO_PATTERNS: RegExp[] = [
63	  /\bauto(?:matic|mated)?[\s-]?reply\b/i,
64	  /\bthis is an automated\b/i,
65	  /\bdo[\s-]?not[\s-]?reply\b/i,
66	  /\bno[\s-]?reply@\b/i,
67	  /\bdelivery (?:status notification|has failed)\b/i,
68	  /\bundeliverable\b/i,
69	  /\bmailer-daemon\b/i,
70	  /\baddress not found\b/i,
71	];
72	
73	const NOT_INTERESTED_PATTERNS: RegExp[] = [
74	  /\bnot interested\b/i,
75	  /\bno thanks?\b/i,
76	  /\bnot (?:a )?(?:good )?(?:fit|match)\b/i,
77	  /\bwe(?:'re| are) (?:all )?(?:set|good)\b/i,
78	  /\balready (?:have|using|work with)\b/i,
79	  /\bplease stop\b/i,
80	];
81	
82	const INTERESTED_PATTERNS: RegExp[] = [
83	  /\b(?:interested|keen|curious)\b/i,
84	  /\btell me more\b/i,
85	  /\b(?:sounds|looks) (?:good|great|interesting)\b/i,
86	  /\b(?:book|schedule|set up|arrange) (?:a )?(?:call|meeting|demo|time)\b/i,
87	  /\bhappy to (?:chat|talk|connect)\b/i,
88	  /\bwhat(?:'s| is) (?:the |your )?(?:pricing|price|cost)\b/i,
89	  /\bhow (?:much|does it work)\b/i,
90	];
91	
92	function anyMatch(text: string, patterns: RegExp[]): boolean {
93	  return patterns.some((re) => re.test(text));
94	}
95	
96	/** Is this reply an unsubscribe / opt-out request? Rule-only, never AI-gated. */
97	export function isUnsubscribeRequest(text: string): boolean {
98	  return anyMatch(text ?? "", UNSUB_PATTERNS);
99	}
100	
101	/**
102	 * Rule-based first pass over the reply text (subject + body). Returns a definite
103	 * class when the rules are confident, else null (hand off to the AI layer). Order
104	 * matters: an unsubscribe phrase wins over everything, then automated messages,
105	 * then out-of-office, then the softer interested/not-interested cues.
106	 */
107	export function ruleClassify(text: string): ReplyClass | null {
108	  const t = (text ?? "").toLowerCase();
109	  if (!t.trim()) return null;
110	  if (anyMatch(t, UNSUB_PATTERNS)) return "UNSUBSCRIBE";
111	  if (anyMatch(t, AUTO_PATTERNS)) return "AUTO_REPLY";
112	  if (anyMatch(t, OOO_PATTERNS)) return "OUT_OF_OFFICE";
113	  if (anyMatch(t, NOT_INTERESTED_PATTERNS)) return "NOT_INTERESTED";
114	  if (anyMatch(t, INTERESTED_PATTERNS)) return "INTERESTED";
115	  return null;
116	}
117	
118	// ---------------------------------------------------------------------------
119	// Class → ConversationStatus / ContactStage mapping (PURE)
120	// ---------------------------------------------------------------------------
121	
122	/** Map a reply class to the conversation status it sets. */
123	export function classToConversationStatus(c: ReplyClass): ConversationStatusValue {
124	  switch (c) {
125	    case "INTERESTED":
126	      return "INTERESTED";
127	    case "NOT_INTERESTED":
128	      return "NOT_INTERESTED";
129	    case "AUTO_REPLY":
130	      return "AUTO_REPLY";
131	    case "OUT_OF_OFFICE":
132	      return "OUT_OF_OFFICE";
133	    case "UNSUBSCRIBE":
134	      return "UNSUBSCRIBE";
135	  }
136	}
137	
138	/**
139	 * Map a reply class to the contact stage it advances to, or null to leave the
140	 * stage at REPLIED (auto-replies / OOO are not a human signal either way). A reply
141	 * has already moved the contact to REPLIED before this is applied.
142	 */
143	export function classToContactStage(c: ReplyClass): ContactStageValue | null {
144	  switch (c) {
145	    case "INTERESTED":
146	      return "INTERESTED";
147	    case "NOT_INTERESTED":
148	      return "LOST";
149	    case "UNSUBSCRIBE":
150	      return "LOST";
151	    case "AUTO_REPLY":
152	    case "OUT_OF_OFFICE":
153	      return null;
154	  }
155	}
156	
157	/** Does this class require a GLOBAL suppression? (Unsubscribe only.) */
158	export function classNeedsSuppression(c: ReplyClass): boolean {
159	  return c === "UNSUBSCRIBE";
160	}
161	
162	/** Parse a raw AI answer down to one of the five buckets, or null if unparseable. */
163	export function parseAiClass(raw: string): ReplyClass | null {
164	  const u = (raw ?? "").toUpperCase();
165	  const buckets: ReplyClass[] = ["UNSUBSCRIBE", "OUT_OF_OFFICE", "AUTO_REPLY", "NOT_INTERESTED", "INTERESTED"];
166	  for (const b of buckets) {
167	    if (u.includes(b) || u.includes(b.replace(/_/g, " "))) return b;
168	  }
169	  return null;
170	}
171	
172	const CLASSIFY_SYSTEM = `You classify a single inbound reply to a B2B cold outreach email into EXACTLY ONE bucket. Answer with ONLY the bucket word, nothing else.
173	
174	Buckets:
175	- INTERESTED — wants to learn more, book a call/demo, asks about pricing, positive engagement.
176	- NOT_INTERESTED — declines, not a fit, already sorted, asks to be left alone (but NOT a formal unsubscribe).
177	- OUT_OF_OFFICE — an automatic away/vacation message.
178	- AUTO_REPLY — any other automated message (ticket auto-ack, mailer-daemon, no-reply notice).
179	- UNSUBSCRIBE — explicitly asks to unsubscribe / opt out / be removed / stop all contact.
180	
181	Reply with one of: INTERESTED, NOT_INTERESTED, OUT_OF_OFFICE, AUTO_REPLY, UNSUBSCRIBE.`;
182	
183	/**
184	 * Full classification for a captured reply.
185	 *
186	 *  - Rule pass runs first and is authoritative for UNSUBSCRIBE / OOO / AUTO_REPLY.
187	 *  - If the rules are ambiguous AND an Anthropic key is available, ask Claude to
188	 *    pick a bucket (used mainly to separate INTERESTED vs NOT_INTERESTED).
189	 *  - With no key and ambiguous rules, returns null → the caller leaves the
190	 *    conversation OPEN (honest: we didn't classify it).
191	 *
192	 * Never throws — a classification failure must not break reply ingestion.
193	 */
194	export async function classifyReply(
195	  subject: string,
196	  body: string,
197	  opts: { anthropicKeyEnc?: string | null } = {},
198	): Promise<ReplyClass | null> {
199	  const text = `${subject ?? ""}\n\n${body ?? ""}`.trim();
200	  const rule = ruleClassify(text);
201	  // Rules are decisive for the "safety" buckets — never let AI override them.
202	  if (rule === "UNSUBSCRIBE" || rule === "AUTO_REPLY" || rule === "OUT_OF_OFFICE") return rule;
203	
204	  const key = effectiveKeyFor(opts);
205	  if (!key) return rule; // no AI available — trust the (possibly null) rule verdict
206	
207	  try {
208	    const messages: ClaudeMessage[] = [
209	      { role: "user", content: `Subject: ${subject ?? ""}\n\nBody:\n${(body ?? "").slice(0, 4000)}` },
210	    ];
211	    const answer = await askClaude(key, messages, CLASSIFY_SYSTEM, { maxTokens: 16, timeoutMs: 20_000 });
212	    return parseAiClass(answer) ?? rule;
213	  } catch {
214	    return rule;
215	  }
216	}
