220	/**
221	 * Process due sends for one eligible campaign. Returns the number actually sent so
222	 * the caller can respect the per-sweep budget across campaigns.
223	 */
224	async function processDueSends(
225	  campaign: CampaignForSend,
226	  identity: SendIdentity,
227	  ctx: {
228	    now: Date;
229	    transport: MailTransport;
230	    ceiling: number;
231	    warmupEnabled: boolean;
232	    footerDisclosure: string;
233	    budget: number;
234	  },
235	): Promise<number> {
236	  if (ctx.budget <= 0) return 0;
237	  if (!withinSendWindow(campaign, ctx.now)) return 0;
238	
239	  // ===== Phase 3 — rotation pool =====
240	  // If the brand has ACTIVE inboxes, distribute sends across them honouring each
241	  // inbox's warmup limit + dailyCap + min gap (rotation.selectNextInbox). Otherwise
242	  // fall back to the Phase 2 brand-level warmup cap (unchanged).
243	  const pool = await loadBrandRotationPool(campaign.brandId, identity, ctx.now);
244	  const useRotation = pool.length > 0;
245	  const poolById = new Map(pool.map((p) => [p.candidate.id, p]));
246	
247	  // Per-inbox daily cap (warmup-aware). Counts REAL sends today for the brand.
248	  const brand = await db.brand.findUnique({
249	    where: { id: campaign.brandId },
250	    select: { warmupStartedAt: true, dailySendCap: true },
251	  });
252	  const cap = effectiveDailyCap({
253	    warmupStartedAt: brand?.warmupStartedAt ?? null,
254	    ceiling: brand?.dailySendCap ?? ctx.ceiling,
255	    warmupEnabled: ctx.warmupEnabled,
256	    now: ctx.now,
257	  });
258	  let sentToday = await db.coldSend.count({
259	    where: { campaign: { brandId: campaign.brandId }, sentAt: { gte: startOfUtcDay(ctx.now) } },
260	  });
261	  if (!useRotation && sentToday >= cap) return 0;
262	
263	  // Suppression rows for this brand, loaded once (GLOBAL + this brand's BRAND tier).
264	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
265	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
266	    select: { email: true, domain: true, scope: true, brandId: true },
267	  });
268	
269	  const due = await db.coldSend.findMany({
270	    where: {
271	      campaignId: campaign.id,
272	      status: "QUEUED",
273	      stepId: { not: null },
274	      scheduledFor: { lte: ctx.now },
275	    },
276	    orderBy: { scheduledFor: "asc" },
277	    take: ctx.budget,
278	    include: {
279	      contact: { select: { id: true, email: true, fullName: true, title: true, business: { select: { name: true } } } },
280	      step: { select: { subject: true, bodyMarkdown: true } },
281	    },
282	  });
283	
284	  let sent = 0;
285	  for (const s of due) {
286	    if (!s.step || !s.contact) continue;
287	
288	    // GUARDRAIL #4 — re-check suppression immediately before the send.
289	    if (isSuppressed(s.contact.email, campaign.brandId, suppressions)) {
290	      await db.coldSend.update({ where: { id: s.id }, data: { status: "SUPPRESSED" } });
291	      continue;
292	    }
293	
294	    // Pick the sending inbox (rotation) or fall back to the brand identity + cap.
295	    let chosen: PoolInbox | null = null;
296	    if (useRotation) {
297	      const cand = selectNextInbox(pool.map((p) => p.candidate), ctx.now);
298	      if (!cand) break; // no eligible inbox right now — leave the rest QUEUED
299	      chosen = poolById.get(cand.id) ?? null;
300	      if (!chosen) break;
301	    } else if (sentToday >= cap) {
302	      break; // brand-level cap reached
303	    }
304	
305	    const sendIdentity = chosen ? chosen.identity : identity;
306	    const token = openTrackingToken(s.id);
307	    const msg = buildMessage({
308	      identity: sendIdentity,
309	      step: s.step,
310	      contact: s.contact,
311	      sendId: s.id,
312	      footerDisclosure: ctx.footerDisclosure,
313	      track: true,
314	    });
315	
316	    try {
317	      const res = await ctx.transport.send(msg);
318	      const sentAt = new Date();
319	      await db.coldSend.update({
320	        where: { id: s.id },
321	        data: {
322	          status: "SENT",
323	          sentAt,
324	          inboxId: chosen?.candidate.id ?? null,
325	          messageId: res.messageId ?? null,
326	          trackingToken: token,
327	          error: null,
328	        },
329	      });
330	      await db.emailEvent.create({ data: { sendId: s.id, type: "SENT" } });
331	      await recordDeliverability("SENT", {
332	        inboxId: chosen?.candidate.id ?? null,
333	        sendingDomainId: chosen?.sendingDomainId ?? null,
334	        campaignId: campaign.id,
335	        contactId: s.contact.id,
336	        sendId: s.id,
337	      });
338	      if (chosen) {
339	        // Advance the rotation state so successive picks rotate + honour the gap.
340	        chosen.candidate.sentToday += 1;
341	        chosen.candidate.lastSendAt = sentAt;
342	        await db.inbox.update({ where: { id: chosen.candidate.id }, data: { lastSendAt: sentAt } }).catch(() => null);
343	      }
344	      sentToday++;
345	      sent++;
346	    } catch (err) {
347	      const error = String((err as Error)?.message ?? err).slice(0, 500);
348	      await db.coldSend.update({ where: { id: s.id }, data: { status: "FAILED", error, inboxId: chosen?.candidate.id ?? null, trackingToken: token } });
349	      await db.emailEvent.create({ data: { sendId: s.id, type: "FAILED", meta: error } });
350	      await recordDeliverability("FAILED", {
351	        inboxId: chosen?.candidate.id ?? null,
352	        sendingDomainId: chosen?.sendingDomainId ?? null,
353	        campaignId: campaign.id,
354	        contactId: s.contact.id,
355	        sendId: s.id,
356	        meta: error,
357	      });
358	      await logEvent("error", "coldemail.send.fail", { campaignId: campaign.id, sendId: s.id, error });
359	    }
360	
361	    await sleep(jitter());
362	  }
363	  return sent;
364	}
