1	// Cold Email Engine — IMAP reply poller (Overhaul Phase 1).
2	//
3	// Registered on the worker loop (worker/index.ts). For each Inbox that has REAL
4	// IMAP credentials it connects, fetches messages newer than the stored UID
5	// bookmark, and for every reply from a known contact it:
6	//   1. upserts a Conversation + appends an INBOUND Message (idempotent on UID),
7	//   2. moves the contact to stage REPLIED,
8	//   3. HALTS the contact's remaining queued sends (mail-side reply detection),
9	//   4. writes a REPLY EmailEvent + DeliverabilityEvent for the analytics spine,
10	//   5. classifies the reply (rules first, then Claude if a key exists) and sets the
11	//      conversation status + contact stage; an UNSUBSCRIBE writes a GLOBAL Suppression,
12	//   6. fires reply / interested / unsubscribe webhooks.
13	//
14	// SAFETY: this is send-INDEPENDENT and creds-gated. An inbox with a blank imapHost
15	// is never touched — no creds, no connection. It reads mail; it never sends here.
16	// Degrades gracefully with no ANTHROPIC_API_KEY (the reply stays classified only by
17	// rules, else left OPEN). Never throws to the caller — a bad mailbox is logged and
18	// skipped so one inbox can't stall the sweep.
19	
20	import { ImapFlow } from "imapflow";
21	import { simpleParser, type ParsedMail } from "mailparser";
22	import { db } from "../lib/db";
23	import { decryptSecret } from "../lib/crypto-box";
24	import { normalizeEmail } from "../lib/coldemail/compliance";
25	import { matchColdSendId, buildSentIndex } from "../lib/coldemail/inbox-match";
26	import { normalizeMessageId } from "../lib/coldemail/threading";
27	import {
28	  classifyReply,
29	  isUnsubscribeRequest,
30	  classToConversationStatus,
31	  classToContactStage,
32	  classNeedsSuppression,
33	  type ReplyClass,
34	} from "../lib/coldemail/classify";
35	import { fireWebhooks } from "../lib/coldemail/webhooks";
36	import { logEvent } from "../lib/log";
37	
38	type PollInbox = {
39	  id: string;
40	  email: string;
41	  imapHost: string;
42	  imapPort: number;
43	  imapUser: string;
44	  imapPassEnc: string;
45	  imapTls: boolean;
46	  lastImapUid: number;
47	};
48	
49	/** Cap on messages examined per inbox per sweep — keeps a first poll bounded. */
50	const MAX_MESSAGES_PER_INBOX = 200;
51	
52	/** The sweep entrypoint. Polls every credentialed inbox; isolates failures. */
53	export async function coldEmailInboxPoll(): Promise<void> {
54	  let inboxes: PollInbox[];
55	  try {
56	    inboxes = await db.inbox.findMany({
57	      where: { imapHost: { not: "" }, imapUser: { not: "" } },
58	      select: {
59	        id: true,
60	        email: true,
61	        imapHost: true,
62	        imapPort: true,
63	        imapUser: true,
64	        imapPassEnc: true,
65	        imapTls: true,
66	        lastImapUid: true,
67	      },
68	    });
69	  } catch {
70	    return; // tables not migrated on this env — behave like a no-op
71	  }
72	  if (inboxes.length === 0) return; // no credentialed inboxes — nothing connects
73	
74	  for (const ib of inboxes) {
75	    try {
76	      await pollOneInbox(ib);
77	    } catch (err) {
78	      await logEvent("error", "coldemail.inbox.poll", { inboxId: ib.id, message: String((err as Error)?.message ?? err) });
79	    }
80	  }
81	}
