83	async function pollOneInbox(ib: PollInbox): Promise<void> {
84	  const pass = decryptSecret(ib.imapPassEnc);
85	  if (!pass) return; // password absent or undecryptable — cannot connect, skip quietly
86	
87	  const client = new ImapFlow({
88	    host: ib.imapHost,
89	    port: ib.imapPort || 993,
90	    secure: ib.imapTls,
91	    auth: { user: ib.imapUser, pass },
92	    logger: false,
93	    emitLogs: false,
94	  });
95	
96	  let maxUid = ib.lastImapUid;
97	  await client.connect();
98	  try {
99	    const lock = await client.getMailboxLock("INBOX");
100	    try {
101	      const startUid = ib.lastImapUid + 1;
102	      let seen = 0;
103	      // UID-based fetch: `${startUid}:*` returns everything above the bookmark. The
104	      // `X:*` IMAP quirk can echo the latest message even when none is newer, so we
105	      // re-check `uid > lastImapUid` per row.
106	      for await (const msg of client.fetch(`${startUid}:*`, { uid: true, source: true, envelope: true }, { uid: true })) {
107	        if (seen >= MAX_MESSAGES_PER_INBOX) break;
108	        seen++;
109	        const uid = msg.uid;
110	        if (!uid || uid <= ib.lastImapUid) continue;
111	        if (uid > maxUid) maxUid = uid;
112	        if (!msg.source) continue;
113	        try {
114	          await ingestMessage(ib, uid, await simpleParser(msg.source as Buffer));
115	        } catch (err) {
116	          await logEvent("error", "coldemail.inbox.ingest", { inboxId: ib.id, uid, message: String((err as Error)?.message ?? err) });
117	        }
118	      }
119	    } finally {
120	      lock.release();
121	    }
122	  } finally {
123	    await client.logout().catch(() => null);
124	  }
125	
126	  // Advance the bookmark + stamp the poll even when nothing matched, so we never
127	  // re-scan the same UIDs next sweep.
128	  await db.inbox
129	    .update({ where: { id: ib.id }, data: { lastImapUid: Math.max(maxUid, ib.lastImapUid), lastPolledAt: new Date() } })
130	    .catch(() => null);
131	}
