133	/** Turn one parsed inbound message into a Conversation + Message (+ side effects). */
134	async function ingestMessage(ib: PollInbox, uid: number, parsed: ParsedMail): Promise<void> {
135	  const fromAddr = normalizeEmail(parsed.from?.value?.[0]?.address ?? "");
136	  if (!fromAddr || !fromAddr.includes("@")) return;
137	  // Ignore our own sent copies that may live in this mailbox.
138	  if (fromAddr === normalizeEmail(ib.email)) return;
139	
140	  // Only capture replies from a KNOWN contact (a reply to our outreach).
141	  const contact = await db.contact.findUnique({ where: { email: fromAddr }, select: { id: true, fullName: true, stage: true } });
142	  if (!contact) return;
143	
144	  const messageId = normalizeMessageId(parsed.messageId) || `<imap-${ib.id}-${uid}@nxeon>`;
145	  // Idempotency: if we already stored this Message-ID in this inbox's thread, stop.
146	  const dupe = await db.message.findFirst({
147	    where: { messageId, conversation: { inboxId: ib.id } },
148	    select: { id: true },
149	  });
150	  if (dupe) return;
151	
152	  const subject = (parsed.subject ?? "").slice(0, 300);
153	  const bodyText = (parsed.text ?? "").trim();
154	  const bodyHtml = typeof parsed.html === "string" ? parsed.html : "";
155	  const inReplyTo = normalizeMessageId(parsed.inReplyTo);
156	  const references = Array.isArray(parsed.references)
157	    ? parsed.references.map(normalizeMessageId).join(" ")
158	    : normalizeMessageId(parsed.references as string | undefined);
159	  const receivedAt = parsed.date ?? new Date();
160	
161	  // ---- Match the originating send (threading first, recipient fallback) ----
162	  const contactSends = await db.coldSend.findMany({
163	    where: { contactId: contact.id, inboxId: ib.id },
164	    orderBy: { createdAt: "desc" },
165	    select: { id: true, messageId: true, campaignId: true },
166	  });
167	  const matchedSendId =
168	    matchColdSendId(inReplyTo, references, buildSentIndex(contactSends)) ?? (contactSends[0]?.id ?? null);
169	  const matchedCampaignId =
170	    contactSends.find((s) => s.id === matchedSendId)?.campaignId ?? contactSends[0]?.campaignId ?? null;
171	
172	  // ---- Upsert the conversation ----
173	  const convo = await db.conversation.upsert({
174	    where: { inboxId_contactId: { inboxId: ib.id, contactId: contact.id } },
175	    create: {
176	      inboxId: ib.id,
177	      contactId: contact.id,
178	      campaignId: matchedCampaignId,
179	      subject,
180	      status: "REPLIED",
181	      lastMessageAt: receivedAt,
182	      unread: true,
183	    },
184	    update: {
185	      lastMessageAt: receivedAt,
186	      unread: true,
187	      // Fill campaign if we now know it and didn't before.
188	      ...(matchedCampaignId ? { campaignId: matchedCampaignId } : {}),
189	    },
190	    select: { id: true, status: true },
191	  });
192	
193	  // ---- Append the inbound message ----
194	  await db.message.create({
195	    data: {
196	      conversationId: convo.id,
197	      direction: "INBOUND",
198	      fromAddr,
199	      toAddr: normalizeEmail(ib.email),
200	      subject,
201	      bodyText: bodyText.slice(0, 100_000),
202	      bodyHtml: bodyHtml.slice(0, 200_000),
203	      messageId,
204	      inReplyTo,
205	      references,
206	      coldSendId: matchedSendId,
207	      receivedAt,
208	    },
209	  });
210	
211	  // ---- Advance the contact to REPLIED (never downgrade a warmer stage) ----
212	  await db.contact.updateMany({
213	    where: { id: contact.id, stage: { in: ["NEW", "CONTACTED"] } },
214	    data: { stage: "REPLIED" },
215	  });
216	
217	  // ---- HALT the contact's remaining queued sends (mail-side reply detection) ----
218	  await db.coldSend
219	    .updateMany({
220	      where: { contactId: contact.id, status: "QUEUED" },
221	      data: { status: "CANCELLED", error: "Halted: contact replied" },
222	    })
223	    .catch(() => null);
224	
225	  // ---- Analytics spine: REPLY event(s) ----
226	  if (matchedSendId) {
227	    await db.emailEvent.create({ data: { sendId: matchedSendId, type: "REPLY" } }).catch(() => null);
228	  }
229	  await db.deliverabilityEvent
230	    .create({
231	      data: {
232	        type: "REPLY",
233	        inboxId: ib.id,
234	        campaignId: matchedCampaignId,
235	        contactId: contact.id,
236	        sendId: matchedSendId,
237	        provider: "imap",
238	      },
239	    })
240	    .catch(() => null);
241	
242	  // ---- Classify (rules always; Claude only if a key exists) ----
243	  const cls = await classifyReply(subject, bodyText, {});
244	  const unsub = cls === "UNSUBSCRIBE" || isUnsubscribeRequest(`${subject}\n${bodyText}`);
245	
246	  const finalStatus = cls ? classToConversationStatus(cls) : convo.status === "OPEN" ? "REPLIED" : "REPLIED";
247	  await db.conversation.update({
248	    where: { id: convo.id },
249	    data: { status: finalStatus, category: cls ?? "" },
250	  });
251	
252	  // Stage advancement from the classification (don't clobber WON/MEETING_BOOKED).
253	  const stageAdvance = cls ? classToContactStage(cls) : null;
254	  if (stageAdvance) {
255	    await db.contact
256	      .updateMany({ where: { id: contact.id, stage: { notIn: ["WON", "MEETING_BOOKED"] } }, data: { stage: stageAdvance } })
257	      .catch(() => null);
258	  }
259	
260	  // ---- Unsubscribe → GLOBAL suppression (idempotent) ----
261	  if (unsub) {
262	    const existing = await db.suppression.findFirst({ where: { email: fromAddr, scope: "GLOBAL" }, select: { id: true } });
263	    if (!existing) {
264	      await db.suppression.create({ data: { email: fromAddr, scope: "GLOBAL", reason: "UNSUBSCRIBE" } }).catch(() => null);
265	    }
266	    await db.emailEvent.create({ data: { sendId: matchedSendId ?? "", type: "UNSUBSCRIBE" } }).catch(() => null);
267	  }
268	
269	  // ---- Webhooks ----
270	  await fireWebhookForReply(convo.id, fromAddr, contact.fullName, matchedCampaignId, ib.email, finalStatus, bodyText, cls, unsub);
271	}
272	
273	/** Fan out the reply / interested / unsubscribe webhook events. Best-effort. */
274	async function fireWebhookForReply(
275	  conversationId: string,
276	  contactEmail: string,
277	  contactName: string | null | undefined,
278	  campaignId: string | null,
279	  inboxEmail: string,
280	  status: string,
281	  body: string,
282	  cls: ReplyClass | null,
283	  unsub: boolean,
284	): Promise<void> {
285	  const base = {
286	    conversationId,
287	    contactEmail,
288	    contactName: contactName ?? undefined,
289	    campaignId,
290	    inboxEmail,
291	    status,
292	    snippet: body.replace(/\s+/g, " ").trim().slice(0, 280),
293	    occurredAt: new Date().toISOString(),
294	  };
295	  await fireWebhooks("reply", base);
296	  if (cls === "INTERESTED") await fireWebhooks("interested", base);
297	  if (unsub) await fireWebhooks("unsubscribe", base);
298	}
