129	/** Aggregate this UTC day's DeliverabilityEvent rows into MetricsDaily by scope. */
130	export async function coldEmailRollupSweep(): Promise<void> {
131	  const now = new Date();
132	  const day0 = startOfUtcDay(now);
133	
134	  let events;
135	  try {
136	    events = await db.deliverabilityEvent.findMany({
137	      where: { occurredAt: { gte: day0 } },
138	      select: { type: true, inboxId: true, sendingDomainId: true, campaignId: true },
139	    });
140	  } catch {
141	    return; // not migrated
142	  }
143	
144	  const byInbox: Grouped = new Map();
145	  const byDomain: Grouped = new Map();
146	  const byCampaign: Grouped = new Map();
147	  const brandByDomain = new Map<string, string>();
148	
149	  for (const e of events) {
150	    const delta = EVENT_TO_COUNT[e.type];
151	    if (!delta) continue;
152	    bump(byInbox, e.inboxId, delta);
153	    bump(byDomain, e.sendingDomainId, delta);
154	    bump(byCampaign, e.campaignId, delta);
155	  }
156	
157	  try {
158	    await upsertMetrics("INBOX", day0, byInbox);
159	    await upsertMetrics("DOMAIN", day0, byDomain);
160	    await upsertMetrics("CAMPAIGN", day0, byCampaign);
161	  } catch (err) {
162	    await logEvent("error", "coldemail.rollup.upsert", { message: String(err) });
163	  }
164	
165	  // Roll domains up to their brand for the agency/multi-client view.
166	  const byBrand: Grouped = new Map();
167	  for (const [domainId, c] of byDomain) {
168	    let brandId = brandByDomain.get(domainId);
169	    if (!brandId) {
170	      const d = await db.sendingDomain.findUnique({ where: { id: domainId }, select: { brandId: true } }).catch(() => null);
171	      brandId = d?.brandId;
172	      if (brandId) brandByDomain.set(domainId, brandId);
173	    }
174	    if (brandId) bump(byBrand, brandId, c);
175	  }
176	  await upsertMetrics("BRAND", day0, byBrand).catch(() => null);
177	
178	  // Auto-pause pass over the trailing window.
179	  const thresholds = await loadThresholds();
180	  await evaluateInboxes(thresholds);
181	  await evaluateDomains(thresholds);
182	}
