197	/** RateStats for a scope over a trailing window (default 7 days). */
198	async function statsForScope(where: Record<string, unknown>, sinceDays = 7): Promise<RateStats> {
199	  const since = new Date(Date.now() - sinceDays * 86_400_000);
200	  const rows = await db.deliverabilityEvent
201	    .groupBy({ by: ["type"], where: { ...where, occurredAt: { gte: since } }, _count: { _all: true } })
202	    .catch(() => [] as { type: string; _count: { _all: number } }[]);
203	  let sent = 0,
204	    delivered = 0,
205	    bounces = 0,
206	    complaints = 0;
207	  for (const r of rows as { type: string; _count: { _all: number } }[]) {
208	    const n = r._count._all;
209	    if (r.type === "SENT") sent += n;
210	    else if (r.type === "DELIVERED") delivered += n;
211	    else if (r.type === "HARD_BOUNCE" || r.type === "SOFT_BOUNCE") bounces += n;
212	    else if (r.type === "COMPLAINT") complaints += n;
213	  }
214	  return { sent, delivered, bounces, complaints };

