  VALID
  RISKY
  INVALID
  // ---- LEAD-DB overhaul (append-only — never reorder/remove) ----
  UNVERIFIED // default for a freshly-imported lead (not yet verified)
  HARD_BOUNCED // permanent 5xx failure — dead forever
  SOFT_BOUNCED // transient 4xx failure(s) — still retried until the dead threshold
  COMPLAINED // marked us as spam — dead + suppressed
  UNSUBSCRIBED // opted out — dead + suppressed
  DEAD // sunset: too many soft bounces / no engagement — dead + suppressed
}

