// Cold Email Engine — LEAD-DATABASE hygiene core.
//
// PURE + unit-testable (no DB, no I/O), same discipline as compliance.ts. This is
// the single source of truth for the lead-database's health model:
//
//   * which email statuses are MAILABLE (may be added to a campaign),
//   * how an SMTP result classifies as a HARD (permanent 5xx) or SOFT (transient
//     4xx) bounce,
//   * how a bounce / complaint / unsubscribe transitions a contact's health
//     ("bounce → dead" pipeline), and
//   * an idempotent recompute of a contact's status from its aggregate event
//     counts (used by the reconciliation sweep).
//
// RESEARCH APPLIED (see docs/DOCUMENTATION.md for citations):
//   - Hard bounce (5xx) = permanent → suppress after ONE occurrence, dead forever.
//   - Soft bounce (4xx) = transient → retry; suppress only after N consecutive
//     failures (default 3). Over-aggressive soft suppression loses valid contacts.
//   - Spam complaint → suppress immediately (Gmail caps complaint rate at 0.3%,
//     target < 0.1%).
//   - Unsubscribe / "not interested" reply → treat as opt-out, suppress same-day.
//   - Merge suppression globally so a dead/opted-out address is never re-mailed by
//     ANY brand — and never resurrected on re-import.

// ---------------------------------------------------------------------------
// Status model (string literals so this module never imports the Prisma client
// and stays importable in a DB-less test).
// ---------------------------------------------------------------------------

export type EmailStatusValue =
  | "UNKNOWN"
  | "UNVERIFIED"
  | "VALID"
  | "RISKY"
  | "INVALID"
  | "HARD_BOUNCED"
  | "SOFT_BOUNCED"
  | "COMPLAINED"
  | "UNSUBSCRIBED"
  | "DEAD";

/**
 * Statuses a contact may still be emailed at. UNKNOWN is legacy-equivalent to
 * UNVERIFIED. SOFT_BOUNCED stays mailable ON PURPOSE — a soft bounce is transient,
 * so the contact is retried until it crosses the dead threshold (then → DEAD).
 */
export const MAILABLE_STATUSES: readonly EmailStatusValue[] = [
  "UNKNOWN",
  "UNVERIFIED",
  "VALID",
  "RISKY",
  "SOFT_BOUNCED",
];

/**
 * Terminal "do-not-contact" statuses. A contact here is excluded from every future
 * campaign and is NEVER resurrected by a re-import (see import.ts).
 */
export const DEAD_STATUSES: readonly EmailStatusValue[] = [
  "INVALID",
  "HARD_BOUNCED",
  "COMPLAINED",
  "UNSUBSCRIBED",
  "DEAD",
];

/** Default number of soft (4xx) bounces before a contact is sunset to DEAD. */
export const DEFAULT_SOFT_BOUNCE_DEAD_THRESHOLD = 3;

/** Is this status one we may still email? */
export function isMailableStatus(status: EmailStatusValue | string | null | undefined): boolean {
  return MAILABLE_STATUSES.includes((status ?? "UNVERIFIED") as EmailStatusValue);
}

/** Is this status terminal (dead / suppressed)? */
export function isDeadStatus(status: EmailStatusValue | string | null | undefined): boolean {
  return DEAD_STATUSES.includes((status ?? "") as EmailStatusValue);
}

/**
 * Final mailability of a contact: a mailable STATUS **and** not globally
 * suppressed. This is the one predicate campaign-build + preview consult.
 */
export function isMailable(input: { emailStatus: EmailStatusValue | string; suppressed?: boolean }): boolean {
  if (input.suppressed) return false;
  return isMailableStatus(input.emailStatus);
}

// ---------------------------------------------------------------------------
// Bounce classification — 5xx permanent (HARD) vs 4xx transient (SOFT)
// ---------------------------------------------------------------------------

export type BounceType = "HARD" | "SOFT";

/**
 * Classify a bounce from an SMTP status. Accepts:
 *   - a numeric basic code (e.g. 550, 421),
 *   - a string basic code ("550"),
 *   - an enhanced DSN code ("5.1.1", "4.2.2"),
 *   - a raw DSN line beginning with the code.
 * Returns "HARD" for 5xx (permanent), "SOFT" for 4xx (transient), or null if the
 * code is not a 4/5xx failure (2xx/3xx or unparseable).
 */
export function classifyBounceCode(code: number | string | null | undefined): BounceType | null {
  if (code == null) return null;
  const s = String(code).trim();
  if (!s) return null;
  // First digit of the basic class. Handle "550", "5.1.1", "550 5.1.1 User unknown".
  const first = s[0];
  if (first === "5") return "HARD";
  if (first === "4") return "SOFT";
  const n = Number(s);
  if (Number.isFinite(n)) {
    if (n >= 500 && n < 600) return "HARD";
    if (n >= 400 && n < 500) return "SOFT";
  }
  return null;
}

// ---------------------------------------------------------------------------
// Bounce / complaint / unsubscribe → status transition ("bounce → dead")
// ---------------------------------------------------------------------------

export type HygieneEvent = "HARD_BOUNCE" | "SOFT_BOUNCE" | "COMPLAINT" | "UNSUBSCRIBE";

export type SuppressReason = "BOUNCE" | "COMPLAINT" | "UNSUBSCRIBE";

export type HygieneTransition = {
  /** The contact's new emailStatus. */
  emailStatus: EmailStatusValue;
  /** New absolute bounceCount (soft bounces accumulate; other events leave it). */
  bounceCount: number;
  /** True when this event moved the contact into a terminal/dead state. */
  dead: boolean;
  /** Human-readable reason to stamp on deadReason when `dead`. */
  deadReason: string;
  /** Whether to write a GLOBAL Suppression (never for a soft bounce below threshold). */
  suppress: boolean;
  /** Suppression reason when `suppress`. */
  suppressReason: SuppressReason | null;
  /** Whether to stamp lastBounceAt (bounce events only). */
  stampBounceAt: boolean;
};

/**
 * Apply one hygiene event to a contact's current health. PURE — the caller
 * persists the returned fields and writes the suppression when `suppress`.
 *
 * Rules (research-backed):
 *   HARD_BOUNCE  → HARD_BOUNCED, dead, suppress(BOUNCE), immediately.
 *   COMPLAINT    → COMPLAINED,   dead, suppress(COMPLAINT).
 *   UNSUBSCRIBE  → UNSUBSCRIBED, dead, suppress(UNSUBSCRIBE).
 *   SOFT_BOUNCE  → bounceCount+1; if >= threshold → DEAD + suppress(BOUNCE),
 *                  else SOFT_BOUNCED (still mailable, no suppression).
 *
 * A contact ALREADY in a dead status is sticky: the event is a no-op transition
 * that re-asserts suppression (idempotent) and never resurrects or downgrades it.
 */
export function applyHygieneEvent(
  current: { emailStatus: EmailStatusValue | string; bounceCount?: number | null },
  event: HygieneEvent,
  opts: { softBounceDeadThreshold?: number; reason?: string } = {},
): HygieneTransition {
  const status = (current.emailStatus ?? "UNVERIFIED") as EmailStatusValue;
  const count = Math.max(0, current.bounceCount ?? 0);
  const threshold = clampThreshold(opts.softBounceDeadThreshold);

  // Terminal is sticky — never resurrect. Re-assert suppression so a duplicate
  // event still guarantees the address is suppressed.
  if (isDeadStatus(status)) {
    return {
      emailStatus: status,
      bounceCount: count,
      dead: true,
      deadReason: "",
      suppress: status !== "INVALID", // INVALID predates suppression; don't force it
      suppressReason: status === "COMPLAINED" ? "COMPLAINT" : status === "UNSUBSCRIBED" ? "UNSUBSCRIBE" : "BOUNCE",
      stampBounceAt: false,
    };
  }

  switch (event) {
    case "HARD_BOUNCE":
      return {
        emailStatus: "HARD_BOUNCED",
        bounceCount: count + 1,
        dead: true,
        deadReason: opts.reason || "Hard bounce — permanent 5xx delivery failure (invalid address)",
        suppress: true,
        suppressReason: "BOUNCE",
        stampBounceAt: true,
      };
    case "COMPLAINT":
      return {
        emailStatus: "COMPLAINED",
        bounceCount: count,
        dead: true,
        deadReason: opts.reason || "Spam complaint / feedback-loop report",
        suppress: true,
        suppressReason: "COMPLAINT",
        stampBounceAt: false,
      };
    case "UNSUBSCRIBE":
      return {
        emailStatus: "UNSUBSCRIBED",
        bounceCount: count,
        dead: true,
        deadReason: opts.reason || "Unsubscribed / opted out",
        suppress: true,
        suppressReason: "UNSUBSCRIBE",
        stampBounceAt: false,
      };
    case "SOFT_BOUNCE": {
      const next = count + 1;
      if (next >= threshold) {
        return {
          emailStatus: "DEAD",
          bounceCount: next,
          dead: true,
          deadReason:
            opts.reason || `Sunset after ${next} transient (4xx) soft bounces (threshold ${threshold})`,
          suppress: true,
          suppressReason: "BOUNCE",
          stampBounceAt: true,
        };
      }
      return {
        emailStatus: "SOFT_BOUNCED",
        bounceCount: next,
        dead: false,
        deadReason: "",
        suppress: false,
        suppressReason: null,
        stampBounceAt: true,
      };
    }
  }
}

function clampThreshold(v: number | null | undefined): number {
  const n = Number(v);
  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : DEFAULT_SOFT_BOUNCE_DEAD_THRESHOLD;
}

// ---------------------------------------------------------------------------
// Idempotent recompute from aggregate event counts (reconciliation sweep)
// ---------------------------------------------------------------------------

export type EventCounts = {
  hardBounce?: number;
  softBounce?: number;
  complaint?: number;
  unsubscribe?: number;
};

export type ReconcileResult = {
  emailStatus: EmailStatusValue;
  bounceCount: number;
  dead: boolean;
  deadReason: string;
  suppress: boolean;
  suppressReason: SuppressReason | null;
  /** True when the recompute actually changes the stored status. */
  changed: boolean;
};

/**
 * Recompute a contact's health from the FULL aggregate of its lifetime events.
 * Deterministic + idempotent: running it twice yields the same result, so it is
 * safe to re-run in a sweep. Severity order: complaint > unsubscribe > hard bounce
 * > soft-bounce sunset. A contact with no adverse events keeps its current status
 * (we never downgrade a VALID/RISKY address here — that's verification's job).
 */
export function reconcileEmailStatus(
  counts: EventCounts,
  current: { emailStatus: EmailStatusValue | string; bounceCount?: number | null },
  softBounceDeadThreshold: number = DEFAULT_SOFT_BOUNCE_DEAD_THRESHOLD,
): ReconcileResult {
  const status = (current.emailStatus ?? "UNVERIFIED") as EmailStatusValue;
  const threshold = clampThreshold(softBounceDeadThreshold);
  const hard = Math.max(0, counts.hardBounce ?? 0);
  const soft = Math.max(0, counts.softBounce ?? 0);
  const complaint = Math.max(0, counts.complaint ?? 0);
  const unsub = Math.max(0, counts.unsubscribe ?? 0);

  let next: EmailStatusValue = status;
  let dead = false;
  let deadReason = "";
  let suppress = false;
  let suppressReason: SuppressReason | null = null;

  if (complaint > 0) {
    next = "COMPLAINED";
    dead = true;
    deadReason = "Spam complaint / feedback-loop report";
    suppress = true;
    suppressReason = "COMPLAINT";
  } else if (unsub > 0) {
    next = "UNSUBSCRIBED";
    dead = true;
    deadReason = "Unsubscribed / opted out";
    suppress = true;
    suppressReason = "UNSUBSCRIBE";
  } else if (hard > 0) {
    next = "HARD_BOUNCED";
    dead = true;
    deadReason = "Hard bounce — permanent 5xx delivery failure (invalid address)";
    suppress = true;
    suppressReason = "BOUNCE";
  } else if (soft >= threshold) {
    next = "DEAD";
    dead = true;
    deadReason = `Sunset after ${soft} transient (4xx) soft bounces (threshold ${threshold})`;
    suppress = true;
    suppressReason = "BOUNCE";
  } else if (soft > 0 && isMailableStatus(status)) {
    next = "SOFT_BOUNCED";
  }

  // Never downgrade a contact that is already terminal to something "less dead".
  if (isDeadStatus(status) && !isDeadStatus(next)) {
    next = status;
    dead = true;
  }

  return {
    emailStatus: next,
    bounceCount: soft,
    dead,
    deadReason,
    suppress,
    suppressReason,
    changed: next !== status,
  };
}

// ---------------------------------------------------------------------------
// Presentation helper — the contact status badge shown across the admin UI
// ---------------------------------------------------------------------------

export type StatusBadge = { label: string; tone: "green" | "red" | "amber" | "slate" | "brand" };

/**
 * The single status badge for a contact, folding address-health + engagement into
 * one label: Dead / Bounced / Unsubscribed / Replied / Emailed / Valid / New.
 */
export function contactStatusBadge(c: {
  emailStatus: EmailStatusValue | string;
  timesEmailed?: number | null;
  repliedAt?: Date | string | null;
}): StatusBadge {
  const s = (c.emailStatus ?? "UNVERIFIED") as EmailStatusValue;
  if (s === "HARD_BOUNCED" || s === "DEAD" || s === "INVALID" || s === "SOFT_BOUNCED") {
    return { label: s === "SOFT_BOUNCED" ? "Bounced (soft)" : "Bounced/Dead", tone: "red" };
  }
  if (s === "COMPLAINED") return { label: "Complained", tone: "red" };
  if (s === "UNSUBSCRIBED") return { label: "Unsubscribed", tone: "amber" };
  if (c.repliedAt) return { label: "Replied", tone: "green" };
  if ((c.timesEmailed ?? 0) > 0) return { label: "Emailed", tone: "brand" };
  if (s === "VALID") return { label: "Valid", tone: "green" };
  return { label: "New", tone: "slate" };
}

// Cold Email Engine — LEAD-DATABASE bulk import + continuous ingestion core.
//
// PURE ORCHESTRATION over an injected `LeadStore` so the exact same idempotent
// dedup/ingest logic runs from (a) the admin server action, (b) the operator CLI
// script scripts/import-leads.ts, and (c) the tests (with an in-memory store, no
// DB). The store is the ONLY thing that touches Prisma.
//
// IDEMPOTENCY + HYGIENE GUARANTEES:
//   - Dedup by NORMALIZED email (primary key of a lead). A repeat of an email
//     already seen earlier in the same file is skipped (skippedDup).
//   - An incoming email that matches an existing contact UPDATES it (fills blanks,
//     re-adds to the target list) — never inserts a duplicate. So a re-import of
//     the same file inserts 0.
//   - An incoming email that matches an existing DEAD or globally-SUPPRESSED
//     contact is NOT resurrected (skippedDead) — no update, no re-add to a list.
//   - A brand-new email that is already on the global suppression list is refused
//     (skippedDead) — we never add a suppressed address.
//   - Secondary signal: phone/website(domain) are recorded on the Business but the
//     dedup key is always the email (the only reliable per-person identifier).

import { normalizeEmail, emailDomain, normalizeDomain } from "@/lib/coldemail/compliance";
import { isDeadStatus, type EmailStatusValue } from "@/lib/coldemail/leaddb";

// ---------------------------------------------------------------------------
// Row model + header spec
// ---------------------------------------------------------------------------

/**
 * Canonical field names an import row can carry. The CSV header row is mapped onto
 * these via IMPORT_HEADER_ALIASES; a JSON array uses these keys directly.
 */
export type LeadRow = {
  email?: string;
  fullName?: string;
  title?: string;
  // Business fields:
  name?: string; // business name
  category?: string;
  businessType?: string;
  website?: string;
  phone?: string;
  addressLine?: string;
  city?: string;
  region?: string;
  country?: string;
  companySize?: string;
};

/**
 * Header alias → canonical field. Superset of the legacy Businesses importer so old
 * files keep working. Keys are compared lower-cased + trimmed.
 */
export const IMPORT_HEADER_ALIASES: Record<string, keyof LeadRow> = {
  email: "email",
  "email address": "email",
  "e-mail": "email",
  contactemail: "email",
  fullname: "fullName",
  "full name": "fullName",
  contact: "fullName",
  contactname: "fullName",
  "contact name": "fullName",
  name2: "fullName",
  person: "fullName",
  title: "title",
  role: "title",
  jobtitle: "title",
  "job title": "title",
  name: "name",
  business: "name",
  company: "name",
  "company name": "name",
  organization: "name",
  category: "category",
  industry: "category",
  type: "businessType",
  businesstype: "businessType",
  website: "website",
  url: "website",
  domain: "website",
  phone: "phone",
  tel: "phone",
  telephone: "phone",
  address: "addressLine",
  addressline: "addressLine",
  street: "addressLine",
  city: "city",
  region: "region",
  state: "region",
  province: "region",
  country: "country",
  size: "companySize",
  companysize: "companySize",
  employees: "companySize",
};

/** Human-facing spec for the import UI + docs. */
export const IMPORT_HEADERS_SPEC = {
  required: ["email"],
  recommended: ["name", "fullName", "title"],
  optional: [
    "category",
    "businessType",
    "website",
    "phone",
    "addressLine",
    "city",
    "region",
    "country",
    "companySize",
  ],
};

// ---------------------------------------------------------------------------
// CSV parsing (RFC-4180-ish: quoted fields, embedded commas/newlines, "" escape).
// ---------------------------------------------------------------------------

export function parseCsv(text: string): { headers: string[]; rows: string[][] } {
  const records: string[][] = [];
  let field = "";
  let row: string[] = [];
  let inQuotes = false;
  const src = (text ?? "").replace(/\r\n?/g, "\n");

  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (inQuotes) {
      if (c === '"') {
        if (src[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ",") {
      row.push(field);
      field = "";
    } else if (c === "\n") {
      row.push(field);
      records.push(row);
      row = [];
      field = "";
    } else {
      field += c;
    }
  }
  if (field.length > 0 || row.length > 0) {
    row.push(field);
    records.push(row);
  }

  const nonEmpty = records.filter((r) => r.some((f) => f.trim() !== ""));
  if (nonEmpty.length === 0) return { headers: [], rows: [] };
  const headers = nonEmpty[0].map((h) => h.trim());
  return { headers, rows: nonEmpty.slice(1) };
}

/** Map a parsed CSV (headers + rows) to canonical LeadRow objects. */
export function csvToLeadRows(headers: string[], rows: string[][]): LeadRow[] {
  const cols = headers.map((h) => IMPORT_HEADER_ALIASES[h.trim().toLowerCase()] ?? null);
  return rows.map((r) => {
    const lead: LeadRow = {};
    cols.forEach((field, i) => {
      if (field) lead[field] = (r[i] ?? "").trim();
    });
    return lead;
  });
}

// ---------------------------------------------------------------------------
// Normalisation + validation of a single lead row
// ---------------------------------------------------------------------------

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export type NormalizedLead = {
  email: string;
  domain: string;
  fullName: string;
  title: string;
  business: {
    name: string;
    category: string;
    businessType: string;
    website: string;
    phone: string;
    addressLine: string;
    city: string;
    region: string;
    country: string;
    companySize: string;
  };
};

/**
 * Normalise + validate a row. Returns null when there is no usable email — the lead
 * database is keyed on emailable people, so an email-less row can't be a lead. The
 * business name falls back to the email domain so a name-less row still imports.
 */
export function normalizeLeadRow(raw: LeadRow): NormalizedLead | null {
  const email = normalizeEmail(raw.email);
  if (!email || !EMAIL_RE.test(email)) return null;
  const domain = emailDomain(email);
  const website = (raw.website ?? "").trim();
  const name = (raw.name ?? "").trim() || domain;
  return {
    email,
    domain,
    fullName: (raw.fullName ?? "").trim().slice(0, 160),
    title: (raw.title ?? "").trim().slice(0, 120),
    business: {
      name: name.slice(0, 160),
      category: (raw.category ?? "").trim().slice(0, 120),
      businessType: (raw.businessType ?? "").trim().slice(0, 120),
      website: website ? normalizeDomain(website).slice(0, 200) || website.slice(0, 200) : "",
      phone: (raw.phone ?? "").trim().slice(0, 60),
      addressLine: (raw.addressLine ?? "").trim().slice(0, 200),
      city: (raw.city ?? "").trim().slice(0, 120),
      region: (raw.region ?? "").trim().slice(0, 120),
      country: (raw.country ?? "").trim().slice(0, 120),
      companySize: (raw.companySize ?? "").trim().slice(0, 60),
    },
  };
}

// ---------------------------------------------------------------------------
// The store the ingest orchestrator drives (Prisma in prod, a fake in tests)
// ---------------------------------------------------------------------------

export type ExistingContact = {
  id: string;
  businessId: string;
  emailStatus: EmailStatusValue | string;
  fullName: string;
  title: string;
};

export interface LeadStore {
  /** Find a contact by NORMALIZED email, or null. */
  findContact(email: string): Promise<ExistingContact | null>;
  /** Is this email (or its domain) on the global suppression list? */
  isSuppressed(email: string): Promise<boolean>;
  /** Create a Business, return its id. */
  createBusiness(data: NormalizedLead["business"], batchId: string | null): Promise<string>;
  /** Create a Contact (status UNVERIFIED), return its id. */
  createContact(
    input: { businessId: string; email: string; fullName: string; title: string },
    batchId: string | null,
  ): Promise<string>;
  /** Fill blank fields on an existing contact (never overwrite non-empty). */
  updateContact(
    id: string,
    input: { fullName?: string; title?: string },
    batchId: string | null,
  ): Promise<void>;
  /** Add a contact to a list, idempotently (no-op if already a member). */
  addToList(contactId: string, listId: string): Promise<void>;
  /** Record a lawful-basis consent row for a newly-created contact. */
  recordConsent(contactId: string, source: string): Promise<void>;
}

// ---------------------------------------------------------------------------
// The ingest orchestrator
// ---------------------------------------------------------------------------

export type ImportResult = {
  totalRows: number;
  inserted: number;
  updated: number;
  skippedDead: number;
  skippedDup: number;
  skippedInvalid: number;
  contactIds: string[];
};

export type IngestOptions = {
  store: LeadStore;
  listId: string | null;
  batchId?: string | null;
  recordConsent?: boolean;
  consentSource?: string;
};

/**
 * Ingest normalized-or-raw rows into the lead database, idempotently.
 *
 * For each row (see file header for the full guarantee set): validate → dedup
 * within the file → look up the existing contact → refuse dead/suppressed →
 * update-or-insert → add to the target list. Returns the batch tally.
 */
export async function ingestLeads(rows: LeadRow[], opts: IngestOptions): Promise<ImportResult> {
  const { store, listId, batchId = null, recordConsent = false, consentSource = "bulk import" } = opts;
  const result: ImportResult = {
    totalRows: rows.length,
    inserted: 0,
    updated: 0,
    skippedDead: 0,
    skippedDup: 0,
    skippedInvalid: 0,
    contactIds: [],
  };

  const seen = new Set<string>(); // in-file dedup by normalized email

  for (const raw of rows) {
    const lead = normalizeLeadRow(raw);
    if (!lead) {
      result.skippedInvalid++;
      continue;
    }
    if (seen.has(lead.email)) {
      result.skippedDup++;
      continue;
    }
    seen.add(lead.email);

    const existing = await store.findContact(lead.email);

    if (existing) {
      // NEVER resurrect a dead/suppressed contact.
      if (isDeadStatus(existing.emailStatus) || (await store.isSuppressed(lead.email))) {
        result.skippedDead++;
        continue;
      }
      // Update in place (fill blanks only) + re-add to the list. No duplicate row.
      await store.updateContact(
        existing.id,
        {
          fullName: existing.fullName ? undefined : lead.fullName || undefined,
          title: existing.title ? undefined : lead.title || undefined,
        },
        batchId,
      );
      if (listId) await store.addToList(existing.id, listId);
      result.updated++;
      result.contactIds.push(existing.id);
      continue;
    }

    // Brand-new email: refuse if it's already globally suppressed (opted-out before
    // the contact row existed) — we never add a suppressed address.
    if (await store.isSuppressed(lead.email)) {
      result.skippedDead++;
      continue;
    }

    const businessId = await store.createBusiness(lead.business, batchId);
    const contactId = await store.createContact(
      { businessId, email: lead.email, fullName: lead.fullName, title: lead.title },
      batchId,
    );
    if (listId) await store.addToList(contactId, listId);
    if (recordConsent) await store.recordConsent(contactId, consentSource);
    result.inserted++;
    result.contactIds.push(contactId);
  }

  return result;
}

