import { db } from "@/lib/db";
import { normalizeEmail, normalizeDomain } from "@/lib/coldemail/compliance";
import { getSetting } from "@/lib/settings";
import { logEvent } from "@/lib/log";

export type FeedbackKind = "BOUNCE" | "COMPLAINT";

input.new_string:
import { db } from "@/lib/db";
import { normalizeEmail, normalizeDomain } from "@/lib/coldemail/compliance";
import { getSetting } from "@/lib/settings";
import { logEvent } from "@/lib/log";
import {
  applyHygieneEvent,
  DEFAULT_SOFT_BOUNCE_DEAD_THRESHOLD,
  type HygieneEvent,
  type SuppressReason,
} from "@/lib/coldemail/leaddb";

/**
 * Feedback we can receive about an address. HARD_BOUNCE (permanent 5xx) and
 * SOFT_BOUNCE (transient 4xx) split the old BOUNCE, which is retained as a legacy
 * alias that maps to HARD (permanent) so any existing caller keeps its old
 * suppress-after-one behaviour.
 */
export type FeedbackKind = "HARD_BOUNCE" | "SOFT_BOUNCE" | "COMPLAINT" | "BOUNCE";

/** Map a feedback kind to the hygiene event + the EmailEvent type it records. */
function resolveKind(kind: FeedbackKind): { event: HygieneEvent; eventType: "HARD_BOUNCE" | "SOFT_BOUNCE" | "COMPLAINT" } {
  switch (kind) {
    case "SOFT_BOUNCE":
      return { event: "SOFT_BOUNCE", eventType: "SOFT_BOUNCE" };
    case "COMPLAINT":
      return { event: "COMPLAINT", eventType: "COMPLAINT" };
    case "HARD_BOUNCE":
    case "BOUNCE":
    default:
      return { event: "HARD_BOUNCE", eventType: "HARD_BOUNCE" };
  }
}

async function softBounceThreshold(): Promise<number> {
  const n = Number(await getSetting("coldemail_soft_bounce_dead_threshold"));
  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : DEFAULT_SOFT_BOUNCE_DEAD_THRESHOLD;
}

/**
 * Apply a hygiene event to the CONTACT record (the "bounce → dead" pipeline):
 * transition emailStatus/bounceCount/deadAt/deadReason and report whether a GLOBAL
 * suppression must be written. Pure decision via applyHygieneEvent; this only
 * persists. Returns the suppression instruction for the caller to honour.
 */
export async function applyContactHygiene(
  contactId: string,
  kind: FeedbackKind,
  reason?: string,
): Promise<{ suppress: boolean; suppressReason: SuppressReason | null; dead: boolean }> {
  const contact = await db.contact.findUnique({
    where: { id: contactId },
    select: { emailStatus: true, bounceCount: true },
  });
  if (!contact) return { suppress: false, suppressReason: null, dead: false };

  const { event } = resolveKind(kind);
  const t = applyHygieneEvent(
    { emailStatus: contact.emailStatus, bounceCount: contact.bounceCount },
    event,
    { softBounceDeadThreshold: await softBounceThreshold(), reason },
  );

  await db.contact.update({
    where: { id: contactId },
    data: {
      emailStatus: t.emailStatus as never,
      bounceCount: t.bounceCount,
      ...(t.stampBounceAt ? { lastBounceAt: new Date() } : {}),
      ...(t.dead ? { deadAt: new Date(), ...(t.deadReason ? { deadReason: t.deadReason } : {}) } : {}),
    },
  });

  return { suppress: t.suppress, suppressReason: t.suppressReason, dead: t.dead };
}

