export async function recordFeedback(
  rawEmail: string,
  kind: FeedbackKind,
  opts: { brandId?: string | null; note?: string } = {},
): Promise<{ ok: boolean; suppressed: boolean; brandPaused?: boolean }> {
  const email = normalizeEmail(rawEmail);
  if (!email || !email.includes("@")) return { ok: false, suppressed: false };

  const { eventType } = resolveKind(kind);

  try {
    // 1) Run the "bounce → dead" pipeline on the contact (if we have one). This
    //    transitions emailStatus/bounceCount/deadAt and TELLS US whether to
    //    suppress — a SOFT bounce below the dead threshold must NOT suppress (it's
    //    transient and still retryable).
    const contact = await db.contact.findUnique({ where: { email }, select: { id: true } });
    let suppress = true;
    let suppressReason: SuppressReason = kind === "COMPLAINT" ? "COMPLAINT" : "BOUNCE";
    if (contact) {
      const h = await applyContactHygiene(contact.id, kind, opts.note);
      suppress = h.suppress;
      suppressReason = h.suppressReason ?? suppressReason;
    } else {
      // No contact row to track soft-bounce state — only suppress terminal signals.
      suppress = kind !== "SOFT_BOUNCE";
    }

    // 2) GLOBAL suppression (idempotent), ONLY when the transition demands it. A
    //    dead/complained/unsubscribed address stays bad for every brand.
    if (suppress) {
      const existing = await db.suppression.findFirst({ where: { email, scope: "GLOBAL" }, select: { id: true } });
      if (!existing) {
        await db.suppression.create({ data: { email, scope: "GLOBAL", reason: suppressReason } });
      }
    }

    // 3) Attach an event to the latest send to this address, if one exists, so the
    //    campaign stats reflect the bounce/complaint.
    let brandId = opts.brandId ?? null;
    if (contact) {
      const lastSend = await db.coldSend.findFirst({
        where: { contactId: contact.id },
        orderBy: { createdAt: "desc" },
        select: { id: true, campaign: { select: { brandId: true } } },
      });
      if (lastSend) {
        await db.emailEvent.create({
          data: { sendId: lastSend.id, type: eventType, meta: (opts.note ?? "").slice(0, 300) },
        });
        brandId = brandId ?? lastSend.campaign.brandId;
      }
    }

    // 4) Complaint circuit breaker.
    let brandPaused = false;
    if (kind === "COMPLAINT" && brandId) {
      brandPaused = await maybeTripCircuitBreaker(brandId);
    }

    return { ok: true, suppressed: suppress, brandPaused };
  } catch (err) {
    await logEvent("error", "coldemail.feedback.record", { message: String(err), kind, email });
    return { ok: false, suppressed: false };
  }
}

