// ---------------------------------------------------------------------------
// LEAD-DB hygiene reconciliation sweep
// ---------------------------------------------------------------------------

const ADVERSE_EVENT_TYPES = ["HARD_BOUNCE", "SOFT_BOUNCE", "BOUNCE", "COMPLAINT", "UNSUBSCRIBE"] as const;

/**
 * Idempotently recompute each contact's emailStatus from the FULL aggregate of its
 * lifetime adverse EmailEvents, so a bounce/complaint that arrived by any path
 * (feedback route, SNS, manual entry) is reflected on the contact — and a
 * permanent bounce sets HARD_BOUNCED + a GLOBAL suppression. Scoped to contacts
 * with a recent adverse event so the sweep stays cheap. Never throws.
 */
export async function coldEmailHygieneSweep(sinceDays = 3): Promise<void> {
  const threshold = await softBounceDeadThreshold();
  const since = new Date(Date.now() - sinceDays * 86_400_000);

  let recent;
  try {
    recent = await db.emailEvent.findMany({
      where: { type: { in: ADVERSE_EVENT_TYPES as unknown as string[] }, createdAt: { gte: since } },
      select: { send: { select: { contactId: true } } },
    });
  } catch {
    return; // not migrated
  }

  const contactIds = Array.from(new Set(recent.map((e) => e.send?.contactId).filter((x): x is string => !!x)));
  for (const contactId of contactIds) {
    try {
      await reconcileOneContact(contactId, threshold);
    } catch (err) {
      await logEvent("error", "coldemail.hygiene.reconcile", { contactId, message: String(err) });
    }
  }
}

async function reconcileOneContact(contactId: string, threshold: number): Promise<void> {
  const contact = await db.contact.findUnique({
    where: { id: contactId },
    select: { id: true, email: true, emailStatus: true, bounceCount: true },
  });
  if (!contact) return;

  // Aggregate this contact's lifetime adverse events (legacy BOUNCE counts as hard).
  const rows = await db.emailEvent.groupBy({
    by: ["type"],
    where: { type: { in: ADVERSE_EVENT_TYPES as unknown as string[] }, send: { contactId } },
    _count: { _all: true },
  });
  const counts = { hardBounce: 0, softBounce: 0, complaint: 0, unsubscribe: 0 };
  for (const r of rows as { type: string; _count: { _all: number } }[]) {
    const n = r._count._all;
    if (r.type === "HARD_BOUNCE" || r.type === "BOUNCE") counts.hardBounce += n;
    else if (r.type === "SOFT_BOUNCE") counts.softBounce += n;
    else if (r.type === "COMPLAINT") counts.complaint += n;
    else if (r.type === "UNSUBSCRIBE") counts.unsubscribe += n;
  }

  const res = reconcileEmailStatus(counts, contact, threshold);
  if (!res.changed && !res.suppress) return;

  if (res.changed) {
    await db.contact.update({
      where: { id: contact.id },
      data: {
        emailStatus: res.emailStatus as never,
        bounceCount: res.bounceCount,
        ...(res.dead ? { deadAt: new Date(), ...(res.deadReason ? { deadReason: res.deadReason } : {}) } : {}),
      },
    });
  }

  // Ensure a GLOBAL suppression exists for a now-terminal address (idempotent).
  if (res.suppress && contact.email && res.suppressReason) {
    const existing = await db.suppression.findFirst({ where: { email: contact.email, scope: "GLOBAL" }, select: { id: true } });
    if (!existing) {
      await db.suppression.create({ data: { email: contact.email, scope: "GLOBAL", reason: res.suppressReason } }).catch(() => null);
    }
  }
}

async function softBounceDeadThreshold(): Promise<number> {
  const n = Number(await getSetting("coldemail_soft_bounce_dead_threshold"));
  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : 3;
}

