// ---------------------------------------------------------------------------
// LEAD-DB bulk importer — idempotent ingest into a chosen list + ImportBatch record
// ---------------------------------------------------------------------------

/** Cap rows a single web request ingests; larger files should use scripts/import-leads.ts. */
const IMPORT_MAX_ROWS = 5000;

/**
 * Bulk-import leads (CSV upload or pasted CSV) into the lead database and assign
 * them to a chosen EmailList. Idempotent: dedup by normalized email, update
 * existing / insert new / never duplicate, and NEVER resurrect a dead/suppressed
 * contact. Records an ImportBatch with the tally.
 */
export async function importLeads(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");

  // Accept either an uploaded file or pasted text.
  let csv = String(formData.get("csv") ?? "");
  const file = formData.get("file");
  if ((!csv || !csv.trim()) && file && typeof file === "object" && "text" in file) {
    try {
      csv = await (file as File).text();
    } catch {
      /* ignore */
    }
  }
  if (!csv.trim()) return { error: "Upload a CSV file or paste some rows first." };

  const listId = String(formData.get("listId") ?? "").trim() || null;
  const recordConsentAll = formData.get("recordConsent") === "on" || formData.get("recordConsent") === "true";
  const batchName = String(formData.get("batchName") ?? "").trim() || `Import ${new Date().toISOString().slice(0, 16)}`;
  const source = String(formData.get("source") ?? "paste") === "csv-upload" ? "csv-upload" : "paste";

  const { headers, rows } = parseImportCsv(csv);
  if (headers.length === 0 || rows.length === 0) {
    return { error: "Could not find a header row and at least one data row." };
  }
  if (!headers.map((h) => h.trim().toLowerCase()).some((h) => h === "email" || h.includes("mail"))) {
    return { error: "CSV needs at least an 'email' column." };
  }
  if (rows.length > IMPORT_MAX_ROWS) {
    return {
      error: `That file has ${rows.length} rows — over the ${IMPORT_MAX_ROWS}-row web limit. Use scripts/import-leads.ts for large files.`,
    };
  }

  if (listId) {
    const list = await db.emailList.findUnique({ where: { id: listId }, select: { id: true } });
    if (!list) return { error: "Pick a valid list." };
  }

  const leadRows: LeadRow[] = csvToLeadRows(headers, rows);

  // Create the batch first so new/updated contacts can reference it, then finalise counts.
  const batch = await db.importBatch.create({
    data: { name: batchName.slice(0, 160), source, listId },
    select: { id: true },
  });

  let result;
  try {
    result = await ingestLeads(leadRows, {
      store: prismaLeadStore("import"),
      listId,
      batchId: batch.id,
      recordConsent: recordConsentAll,
      consentSource: "bulk import",
    });
  } catch (err) {
    await logEvent("error", "coldemail.import.leads", { message: String(err), batchId: batch.id });
    return { error: "Import failed partway through. Some rows may have been imported; check the batch record." };
  }

  await db.importBatch.update({
    where: { id: batch.id },
    data: {
      totalRows: result.totalRows,
      inserted: result.inserted,
      updated: result.updated,
      skippedDead: result.skippedDead,
      skippedDup: result.skippedDup,
      skippedInvalid: result.skippedInvalid,
    },
  });

  revalidatePath("/admin/coldemail/import");
  revalidatePath("/admin/coldemail/businesses");
  revalidatePath("/admin/coldemail/lists");
  revalidatePath("/admin/coldemail");
  return {
    ok: true,
    error: `Imported: ${result.inserted} new, ${result.updated} updated, ${result.skippedDead} dead/suppressed skipped, ${result.skippedDup} in-file dupes, ${result.skippedInvalid} invalid.`,
  };
}

