import { isSuppressed, type SuppressionLike } from "../lib/coldemail/compliance.ts";

// ===========================================================================
// Bounce classification — 5xx permanent (HARD) vs 4xx transient (SOFT)
// ===========================================================================

test("classifyBounceCode: 5xx = HARD (permanent)", () => {
  assert.equal(classifyBounceCode(550), "HARD");
  assert.equal(classifyBounceCode("550"), "HARD");
  assert.equal(classifyBounceCode("5.1.1"), "HARD");
  assert.equal(classifyBounceCode("550 5.1.1 User unknown"), "HARD");
});

test("classifyBounceCode: 4xx = SOFT (transient)", () => {
  assert.equal(classifyBounceCode(421), "SOFT");
  assert.equal(classifyBounceCode("452"), "SOFT");
  assert.equal(classifyBounceCode("4.2.2"), "SOFT");
});

test("classifyBounceCode: non-failure / garbage = null", () => {
  assert.equal(classifyBounceCode(250), null);
  assert.equal(classifyBounceCode(""), null);
  assert.equal(classifyBounceCode(null), null);
  assert.equal(classifyBounceCode("nope"), null);
});

// ===========================================================================
// mailable() logic
// ===========================================================================

test("isMailableStatus: mailable set", () => {
  for (const s of ["UNVERIFIED", "UNKNOWN", "VALID", "RISKY", "SOFT_BOUNCED"] as EmailStatusValue[]) {
    assert.equal(isMailableStatus(s), true, `${s} should be mailable`);
  }
});

test("isMailableStatus: dead set is NOT mailable", () => {
  for (const s of ["HARD_BOUNCED", "COMPLAINED", "UNSUBSCRIBED", "DEAD", "INVALID"] as EmailStatusValue[]) {
    assert.equal(isMailableStatus(s), false, `${s} should not be mailable`);
    assert.equal(isDeadStatus(s), true, `${s} should be dead`);
  }
});

test("isMailable: mailable status but globally suppressed => not mailable", () => {
  assert.equal(isMailable({ emailStatus: "VALID", suppressed: false }), true);
  assert.equal(isMailable({ emailStatus: "VALID", suppressed: true }), false);
  assert.equal(isMailable({ emailStatus: "DEAD", suppressed: false }), false);
});

test("null/undefined status defaults to mailable (treated as UNVERIFIED)", () => {
  assert.equal(isMailableStatus(null), true);
  assert.equal(isMailableStatus(undefined), true);
});

// ===========================================================================
// Bounce -> status transitions (the "bounce -> dead" pipeline)
// ===========================================================================

test("HARD bounce => HARD_BOUNCED, dead, suppress(BOUNCE) immediately", () => {
  const t = applyHygieneEvent({ emailStatus: "VALID", bounceCount: 0 }, "HARD_BOUNCE");
  assert.equal(t.emailStatus, "HARD_BOUNCED");
  assert.equal(t.dead, true);
  assert.equal(t.suppress, true);
  assert.equal(t.suppressReason, "BOUNCE");
  assert.equal(isMailableStatus(t.emailStatus), false);
});

test("COMPLAINT => COMPLAINED, dead, suppress(COMPLAINT)", () => {
  const t = applyHygieneEvent({ emailStatus: "VALID", bounceCount: 0 }, "COMPLAINT");
  assert.equal(t.emailStatus, "COMPLAINED");
  assert.equal(t.suppress, true);
  assert.equal(t.suppressReason, "COMPLAINT");
});

test("UNSUBSCRIBE => UNSUBSCRIBED, dead, suppress(UNSUBSCRIBE)", () => {
  const t = applyHygieneEvent({ emailStatus: "RISKY", bounceCount: 0 }, "UNSUBSCRIBE");
  assert.equal(t.emailStatus, "UNSUBSCRIBED");
  assert.equal(t.suppress, true);
  assert.equal(t.suppressReason, "UNSUBSCRIBE");
});

test("SOFT bounce below threshold => SOFT_BOUNCED, still mailable, NOT suppressed", () => {
  const t1 = applyHygieneEvent({ emailStatus: "VALID", bounceCount: 0 }, "SOFT_BOUNCE"); // count -> 1
  assert.equal(t1.emailStatus, "SOFT_BOUNCED");
  assert.equal(t1.bounceCount, 1);
  assert.equal(t1.dead, false);
  assert.equal(t1.suppress, false);
  assert.equal(isMailableStatus(t1.emailStatus), true, "a single soft bounce stays retryable");

  const t2 = applyHygieneEvent({ emailStatus: "SOFT_BOUNCED", bounceCount: 1 }, "SOFT_BOUNCE"); // -> 2
  assert.equal(t2.emailStatus, "SOFT_BOUNCED");
  assert.equal(t2.suppress, false);
});

test("SOFT bounce AT threshold => DEAD + suppress(BOUNCE)", () => {
  // default threshold is 3: third soft bounce flips to DEAD.
  assert.equal(DEFAULT_SOFT_BOUNCE_DEAD_THRESHOLD, 3);
  const t = applyHygieneEvent({ emailStatus: "SOFT_BOUNCED", bounceCount: 2 }, "SOFT_BOUNCE"); // -> 3
  assert.equal(t.emailStatus, "DEAD");
  assert.equal(t.bounceCount, 3);
  assert.equal(t.dead, true);
  assert.equal(t.suppress, true);
  assert.equal(t.suppressReason, "BOUNCE");
});

test("SOFT bounce respects a custom threshold", () => {
  const t = applyHygieneEvent({ emailStatus: "VALID", bounceCount: 0 }, "SOFT_BOUNCE", { softBounceDeadThreshold: 1 });
  assert.equal(t.emailStatus, "DEAD"); // threshold 1 => first soft bounce is fatal
  assert.equal(t.suppress, true);
});

test("a dead contact is sticky — never resurrected by a later event", () => {
  const t = applyHygieneEvent({ emailStatus: "HARD_BOUNCED", bounceCount: 1 }, "SOFT_BOUNCE");
  assert.equal(t.emailStatus, "HARD_BOUNCED"); // unchanged
  assert.equal(t.suppress, true); // still asserts suppression (idempotent)
});

// ===========================================================================
// reconcileEmailStatus — idempotent recompute from aggregate counts
// ===========================================================================

test("reconcile: complaint beats everything (severity order)", () => {
  const r = reconcileEmailStatus({ hardBounce: 2, softBounce: 5, complaint: 1 }, { emailStatus: "VALID" });
  assert.equal(r.emailStatus, "COMPLAINED");
  assert.equal(r.suppress, true);
});

test("reconcile: soft bounces at/over threshold => DEAD; under => SOFT_BOUNCED", () => {
  assert.equal(reconcileEmailStatus({ softBounce: 3 }, { emailStatus: "VALID" }).emailStatus, "DEAD");
  assert.equal(reconcileEmailStatus({ softBounce: 2 }, { emailStatus: "VALID" }).emailStatus, "SOFT_BOUNCED");
});

test("reconcile is idempotent — running twice yields the same result + changed=false the 2nd time", () => {
  const first = reconcileEmailStatus({ hardBounce: 1 }, { emailStatus: "VALID" });
  assert.equal(first.emailStatus, "HARD_BOUNCED");
  assert.equal(first.changed, true);
  const second = reconcileEmailStatus({ hardBounce: 1 }, { emailStatus: first.emailStatus });
  assert.equal(second.emailStatus, "HARD_BOUNCED");
  assert.equal(second.changed, false);
});

test("reconcile never downgrades a clean contact with no adverse events", () => {
  const r = reconcileEmailStatus({}, { emailStatus: "VALID" });
  assert.equal(r.emailStatus, "VALID");
  assert.equal(r.changed, false);
});

// ===========================================================================
// contactStatusBadge presentation
// ===========================================================================

test("contactStatusBadge folds health + engagement", () => {
  assert.equal(contactStatusBadge({ emailStatus: "HARD_BOUNCED" }).tone, "red");
  assert.equal(contactStatusBadge({ emailStatus: "UNSUBSCRIBED" }).label, "Unsubscribed");
  assert.equal(contactStatusBadge({ emailStatus: "VALID", repliedAt: new Date() }).label, "Replied");
  assert.equal(contactStatusBadge({ emailStatus: "UNVERIFIED", timesEmailed: 3 }).label, "Emailed");
  assert.equal(contactStatusBadge({ emailStatus: "UNVERIFIED" }).label, "New");
});

// ===========================================================================
// Campaign-build EXCLUSION of dead contacts (mirrors worker + preview filter)
// ===========================================================================

type Member = { email: string; emailStatus: EmailStatusValue };

/** The exact predicate the scheduler + preview apply per list member. */
function includeInCampaign(m: Member, brandId: string, sup: SuppressionLike[]): boolean {
  if (!isMailableStatus(m.emailStatus)) return false;
  if (isSuppressed(m.email, brandId, sup)) return false;
  return true;
}

test("campaign build excludes dead/bounced/complained/unsubscribed + suppressed contacts", () => {
  const sup: SuppressionLike[] = [{ email: "sup@x.com", scope: "GLOBAL", brandId: null }];
  const members: Member[] = [
    { email: "good@x.com", emailStatus: "VALID" },
    { email: "new@x.com", emailStatus: "UNVERIFIED" },
    { email: "soft@x.com", emailStatus: "SOFT_BOUNCED" }, // still retryable
    { email: "hard@x.com", emailStatus: "HARD_BOUNCED" },
    { email: "dead@x.com", emailStatus: "DEAD" },
    { email: "spam@x.com", emailStatus: "COMPLAINED" },
    { email: "out@x.com", emailStatus: "UNSUBSCRIBED" },
    { email: "sup@x.com", emailStatus: "VALID" }, // mailable status but suppressed
  ];
  const kept = members.filter((m) => includeInCampaign(m, "brand1", sup)).map((m) => m.email);
  assert.deepEqual(kept, ["good@x.com", "new@x.com", "soft@x.com"]);
});

