test("normalizeLeadRow: valid email required; business name falls back to domain", () => {
  const ok = normalizeLeadRow({ email: " Jane@Acme.com ", fullName: "Jane" });
  assert.ok(ok);
  assert.equal(ok!.email, "jane@acme.com");
  assert.equal(ok!.domain, "acme.com");
  assert.equal(ok!.business.name, "acme.com"); // no name given -> domain
  assert.equal(normalizeLeadRow({ email: "not-an-email" }), null);
  assert.equal(normalizeLeadRow({ fullName: "no email" }), null);
});

test("csvToLeadRows maps aliased headers", () => {
  const { headers, rows } = parseCsv("Company,Contact Name,Email\nAcme,Jane Doe,jane@acme.com\n");
  const leads = csvToLeadRows(headers, rows);
  assert.equal(leads.length, 1);
  assert.equal(leads[0].name, "Acme");
  assert.equal(leads[0].fullName, "Jane Doe");
  assert.equal(leads[0].email, "jane@acme.com");
});

// ---- In-memory LeadStore for DB-less ingest testing ----
function makeFakeStore(seed?: {
  contacts?: { email: string; emailStatus: EmailStatusValue; fullName?: string; title?: string }[];
  suppressed?: string[];
}) {
  let bizSeq = 0;
  let conSeq = 0;
  const contacts = new Map<string, ExistingContact>();
  const suppressed = new Set(seed?.suppressed ?? []);
  const listMembers = new Set<string>();
  const createdContacts: string[] = [];
  for (const c of seed?.contacts ?? []) {
    const id = `seed-${conSeq++}`;
    contacts.set(c.email, {
      id,
      businessId: `seedbiz-${id}`,
      emailStatus: c.emailStatus,
      fullName: c.fullName ?? "",
      title: c.title ?? "",
    });
  }
  const store: LeadStore = {
    async findContact(email) {
      return contacts.get(email) ?? null;
    },
    async isSuppressed(email) {
      return suppressed.has(email);
    },
    async createBusiness(_data: NormalizedLead["business"]) {
      return `biz-${bizSeq++}`;
    },
    async createContact(input) {
      const id = `con-${conSeq++}`;
      contacts.set(input.email, {
        id,
        businessId: input.businessId,
        emailStatus: "UNVERIFIED",
        fullName: input.fullName,
        title: input.title,
      });
      createdContacts.push(id);
      return id;
    },
    async updateContact(id, input) {
      for (const [email, c] of contacts) {
        if (c.id === id) {
          contacts.set(email, {
            ...c,
            fullName: input.fullName ?? c.fullName,
            title: input.title ?? c.title,
          });
        }
      }
    },
    async addToList(contactId, listId) {
      listMembers.add(`${listId}:${contactId}`);
    },
    async recordConsent() {
      /* no-op */
    },
  };
  return { store, contacts, listMembers, createdContacts };
}

test("import dedup within a file: a repeated email is skipped (skippedDup)", async () => {
  const { store } = makeFakeStore();
  const rows = [
    { email: "a@x.com", name: "A" },
    { email: "A@X.com", name: "A dup" }, // same normalized email
    { email: "b@x.com", name: "B" },
  ];
  const res = await ingestLeads(rows, { store, listId: "list1" });
  assert.equal(res.inserted, 2);
  assert.equal(res.skippedDup, 1);
});

test("import idempotency: re-importing the same file inserts 0 (all updated)", async () => {
  const { store } = makeFakeStore();
  const rows = [
    { email: "a@x.com", name: "A", fullName: "Ann" },
    { email: "b@x.com", name: "B", fullName: "Bob" },
  ];
  const first = await ingestLeads(rows, { store, listId: "list1" });
  assert.equal(first.inserted, 2);
  assert.equal(first.updated, 0);

  const second = await ingestLeads(rows, { store, listId: "list1" });
  assert.equal(second.inserted, 0, "re-import must add 0 new contacts");
  assert.equal(second.updated, 2, "existing contacts are updated in place");
});

test("import never resurrects a DEAD contact (skippedDead, status unchanged)", async () => {
  const { store, contacts } = makeFakeStore({
    contacts: [{ email: "dead@x.com", emailStatus: "HARD_BOUNCED", fullName: "Old" }],
  });
  const res = await ingestLeads([{ email: "dead@x.com", name: "X", fullName: "New name" }], {
    store,
    listId: "list1",
  });
  assert.equal(res.inserted, 0);
  assert.equal(res.updated, 0);
  assert.equal(res.skippedDead, 1);
  // Untouched — not resurrected, name not overwritten.
  assert.equal(contacts.get("dead@x.com")!.emailStatus, "HARD_BOUNCED");
  assert.equal(contacts.get("dead@x.com")!.fullName, "Old");
});

test("import refuses a brand-new email that is already globally suppressed", async () => {
  const { store, contacts } = makeFakeStore({ suppressed: ["bad@x.com"] });
  const res = await ingestLeads([{ email: "bad@x.com", name: "X" }], { store, listId: "list1" });
  assert.equal(res.inserted, 0);
  assert.equal(res.skippedDead, 1);
  assert.equal(contacts.has("bad@x.com"), false); // never created
});

test("import counts invalid (email-less) rows separately", async () => {
  const { store } = makeFakeStore();
  const res = await ingestLeads([{ name: "No Email Co" }, { email: "ok@x.com", name: "Ok" }], {
    store,
    listId: null,
  });
  assert.equal(res.inserted, 1);
  assert.equal(res.skippedInvalid, 1);
});

