import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, EmptyState, timeAgo } from "@/components/ui/primitives";
import { LeadImportForm } from "@/components/admin/coldemail/Controls";

export const dynamic = "force-dynamic";

const SOURCE_LABEL: Record<string, string> = {
  paste: "Pasted CSV",
  "csv-upload": "Uploaded CSV",
  script: "CLI script",
};

export default async function ColdEmailImport() {
  await requireArea("platform");

  const [lists, batches] = await Promise.all([
    db.emailList.findMany({ orderBy: { createdAt: "desc" }, select: { id: true, name: true } }),
    db.importBatch.findMany({
      orderBy: { createdAt: "desc" },
      take: 50,
      include: { list: { select: { name: true } } },
    }),
  ]);

  const listOptions = lists.map((l) => ({ id: l.id, label: l.name }));

  return (
    <div className="space-y-6">
      <PageHeader
        title="Import leads"
        sub="Bulk-load Businesses + Contacts into the lead database. Idempotent: dedup by email, dead/suppressed contacts are never resurrected."
      />

      <div className="card">
        <p className="section-label mb-4">Import CSV</p>
        <LeadImportForm lists={listOptions} />
      </div>

      <div className="card overflow-x-auto p-0">
        <div className="flex items-center justify-between px-4 pt-4">
          <p className="section-label">Import history</p>
          <p className="text-xs text-slate-500">{batches.length} shown</p>
        </div>
        {batches.length === 0 ? (
          <div className="p-4">
            <EmptyState title="No imports yet" sub="Upload or paste a CSV above to load your first batch." />
          </div>
        ) : (
          <table className="table-shell mt-2 min-w-[880px]">
            <thead>
              <tr>
                <th>Batch</th>
                <th>Source</th>
                <th>List</th>
                <th className="text-right">Rows</th>
                <th className="text-right">New</th>
                <th className="text-right">Updated</th>
                <th className="text-right">Dead skip</th>
                <th className="text-right">Dupes</th>
                <th className="text-right">Invalid</th>
                <th>When</th>
              </tr>
            </thead>
            <tbody>
              {batches.map((b) => (
                <tr key={b.id}>
                  <td className="align-top font-medium text-white">{b.name}</td>
                  <td className="align-top text-slate-400">{SOURCE_LABEL[b.source] ?? b.source}</td>
                  <td className="align-top text-slate-400">{b.list?.name ?? "—"}</td>
                  <td className="align-top text-right text-slate-300">{b.totalRows}</td>
                  <td className="align-top text-right text-emerald-300">{b.inserted}</td>
                  <td className="align-top text-right text-slate-300">{b.updated}</td>
                  <td className="align-top text-right text-red-300">{b.skippedDead}</td>
                  <td className="align-top text-right text-amber-300">{b.skippedDup}</td>
                  <td className="align-top text-right text-slate-500">{b.skippedInvalid}</td>
                  <td className="align-top text-slate-500">{timeAgo(b.createdAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, EmptyState, timeAgo } from "@/components/ui/primitives";
import { contactStatusBadge } from "@/lib/coldemail/leaddb";

export const dynamic = "force-dynamic";

const EVENT_TONE: Record<string, "green" | "red" | "amber" | "slate" | "brand"> = {
  SENT: "slate",
  DELIVERED: "green",
  OPEN: "slate",
  CLICK: "brand",
  REPLY: "green",
  POSITIVE_REPLY: "green",
  HARD_BOUNCE: "red",
  SOFT_BOUNCE: "amber",
  BOUNCE: "red",
  COMPLAINT: "red",
  UNSUBSCRIBE: "amber",
  FAILED: "red",
};

function fmt(d: Date | null | undefined): string {
  return d ? new Date(d).toISOString().slice(0, 16).replace("T", " ") : "—";
}

export default async function ContactDetail({ params }: { params: Promise<{ id: string }> }) {
  await requireArea("platform");
  const { id } = await params;

  const contact = await db.contact.findUnique({
    where: { id },
    include: {
      business: true,
      importBatch: { select: { name: true, createdAt: true } },
      consentRecords: { orderBy: { createdAt: "desc" }, take: 3 },
      sends: {
        orderBy: { createdAt: "desc" },
        include: {
          campaign: { select: { id: true, name: true, brand: { select: { name: true } } } },
          inbox: { select: { email: true } },
          step: { select: { stepOrder: true } },
          events: { orderBy: { createdAt: "desc" } },
        },
      },
      conversations: {
        orderBy: { lastMessageAt: "desc" },
        include: {
          inbox: { select: { email: true } },
          messages: { orderBy: { createdAt: "asc" }, take: 20 },
        },
      },
    },
  });
  if (!contact) notFound();

  const badge = contactStatusBadge(contact);

  // Distinct campaigns this contact appeared in.
  const campaignMap = new Map<string, { name: string; brand: string }>();
  for (const s of contact.sends) {
    if (s.campaign) campaignMap.set(s.campaign.id, { name: s.campaign.name, brand: s.campaign.brand?.name ?? "" });
  }

  // Build a flat, newest-first activity timeline from send events.
  type TL = { at: Date; type: string; campaign: string; inbox: string; meta: string };
  const timeline: TL[] = [];
  for (const s of contact.sends) {
    const camp = s.campaign?.name ?? "—";
    const inbox = s.inbox?.email ?? "(brand relay)";
    for (const e of s.events) {
      timeline.push({ at: e.createdAt, type: e.type, campaign: camp, inbox, meta: e.meta });
    }
  }
  timeline.sort((a, b) => b.at.getTime() - a.at.getTime());

  return (
    <div className="space-y-6">
      <PageHeader
        title={contact.fullName || contact.email}
        sub={contact.title ? `${contact.title} · ${contact.business.name}` : contact.business.name}
      />
      <Link href="/admin/coldemail/businesses" className="text-xs text-brand-300 hover:underline">
        ← Back to businesses
      </Link>

      {/* Identity + status */}
      <div className="card space-y-3">
        <div className="flex flex-wrap items-center gap-3">
          <Badge tone={badge.tone}>{badge.label}</Badge>
          <span className="text-sm text-slate-300">{contact.email}</span>
          <span className="text-xs text-slate-500">Stage: {contact.stage}</span>
          <span className="text-xs text-slate-500">Address health: {contact.emailStatus}</span>
        </div>
        {contact.deadAt && (
          <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
            Dead since {fmt(contact.deadAt)} — {contact.deadReason || "no reason recorded"}. Excluded from all
            future campaigns.
          </div>
        )}
      </div>

      {/* Engagement + health metrics */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6">
        <Metric label="Times emailed" value={String(contact.timesEmailed)} />
        <Metric label="First emailed" value={fmt(contact.firstEmailedAt)} />
        <Metric label="Last emailed" value={fmt(contact.lastEmailedAt)} />
        <Metric label="Replied" value={fmt(contact.repliedAt)} tone={contact.repliedAt ? "green" : "slate"} />
        <Metric label="Bounce count" value={String(contact.bounceCount)} tone={contact.bounceCount ? "red" : "slate"} />
        <Metric label="Last bounce" value={fmt(contact.lastBounceAt)} />
      </div>

      {/* Campaigns */}
      <div className="card">
        <p className="section-label mb-3">Campaigns ({campaignMap.size})</p>
        {campaignMap.size === 0 ? (
          <p className="text-sm text-slate-500">Not part of any campaign yet.</p>
        ) : (
          <ul className="space-y-1 text-sm text-slate-300">
            {Array.from(campaignMap.values()).map((c, i) => (
              <li key={i}>
                {c.name}
                {c.brand && <span className="text-xs text-slate-500"> · {c.brand}</span>}
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Sends (which mailbox sent each email) */}
      <div className="card overflow-x-auto p-0">
        <p className="section-label px-4 pt-4">Sends ({contact.sends.length})</p>
        {contact.sends.length === 0 ? (
          <div className="p-4">
            <EmptyState title="No sends" sub="This contact has not been sent anything yet." />
          </div>
        ) : (
          <table className="table-shell mt-2 min-w-[720px]">
            <thead>
              <tr>
                <th>Campaign</th>
                <th>Step</th>
                <th>Mailbox / inbox</th>
                <th>Status</th>
                <th>Sent</th>
              </tr>
            </thead>
            <tbody>
              {contact.sends.map((s) => (
                <tr key={s.id}>
                  <td className="align-top text-slate-200">{s.campaign?.name ?? "—"}</td>
                  <td className="align-top text-slate-400">{s.step ? `#${s.step.stepOrder + 1}` : "—"}</td>
                  <td className="align-top text-slate-400">{s.inbox?.email ?? "(brand relay)"}</td>
                  <td className="align-top text-slate-400">{s.status}</td>
                  <td className="align-top text-slate-500">{fmt(s.sentAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Activity timeline */}
      <div className="card">
        <p className="section-label mb-3">Activity timeline ({timeline.length})</p>
        {timeline.length === 0 ? (
          <p className="text-sm text-slate-500">No open/click/reply/bounce events recorded.</p>
        ) : (
          <ul className="space-y-2">
            {timeline.slice(0, 60).map((t, i) => (
              <li key={i} className="flex flex-wrap items-center gap-2 text-sm">
                <Badge tone={EVENT_TONE[t.type] ?? "slate"}>{t.type.replace(/_/g, " ").toLowerCase()}</Badge>
                <span className="text-slate-400">{t.campaign}</span>
                <span className="text-xs text-slate-600">via {t.inbox}</span>
                <span className="ml-auto text-xs text-slate-500">{timeAgo(t.at)}</span>
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Conversations */}
      {contact.conversations.length > 0 && (
        <div className="card space-y-4">
          <p className="section-label">Conversations ({contact.conversations.length})</p>
          {contact.conversations.map((c) => (
            <div key={c.id} className="rounded-lg border border-slate-700/60 p-3">
              <div className="flex items-center gap-2">
                <Badge tone="brand">{c.status}</Badge>
                <span className="text-sm text-slate-300">{c.subject || "(no subject)"}</span>
                <span className="ml-auto text-xs text-slate-500">{c.inbox.email}</span>
              </div>
              <ul className="mt-2 space-y-1 text-xs text-slate-400">
                {c.messages.map((m) => (
                  <li key={m.id}>
                    <span className={m.direction === "INBOUND" ? "text-emerald-300" : "text-slate-500"}>
                      {m.direction === "INBOUND" ? "← reply" : "→ sent"}
                    </span>{" "}
                    {(m.bodyText || "").replace(/\s+/g, " ").slice(0, 160) || "(no text)"}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function Metric({ label, value, tone = "slate" }: { label: string; value: string; tone?: "slate" | "green" | "red" }) {
  const colors = { slate: "text-slate-200", green: "text-emerald-300", red: "text-red-300" };
  return (
    <div className="card p-3">
      <p className="text-[12px] text-slate-400">{label}</p>
      <p className={`mt-1 text-sm font-semibold ${colors[tone]}`}>{value}</p>
    </div>
  );
}

