/**
 * Roll a set of contacts up into a lead-health summary for a list / segment card:
 * how many are sendable (mailable), dead, already-emailed, and replied.
 */
export type LeadHealthSummary = { total: number; sendable: number; dead: number; emailed: number; replied: number };

export function summarizeLeadHealth(
  contacts: { emailStatus: EmailStatusValue | string; timesEmailed?: number | null; repliedAt?: Date | string | null }[],
): LeadHealthSummary {
  const s: LeadHealthSummary = { total: contacts.length, sendable: 0, dead: 0, emailed: 0, replied: 0 };
  for (const c of contacts) {
    if (isMailableStatus(c.emailStatus)) s.sendable++;
    else s.dead++;
    if ((c.timesEmailed ?? 0) > 0) s.emailed++;
    if (c.repliedAt) s.replied++;
  }
  return s;
}

