function appHost(): string | null {
  try {
    return process.env.APP_URL ? new URL(process.env.APP_URL).host : null;
  } catch {
    return null;
  }
}

function hhmm(mins: number | null): string {
  if (mins == null) return "";
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

function startOfUtcDay(now = new Date()): Date {
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
}

export default async function ColdEmailCampaignDetail({ params }: { params: Promise<{ id: string }> }) {
  await requireArea("platform");
  const { id } = await params;

  const campaign = await db.coldCampaign.findUnique({
    where: { id },
    include: {
      brand: true,
      list: { select: { name: true, _count: { select: { members: true } } } },
      steps: { orderBy: { stepOrder: "asc" } },
    },
  });
  if (!campaign) notFound();

  const [
    protectedRaw,
    sendingEnabled,
    warmupEnabled,
    warmupCeiling,

input.new_string:
