  getSettingBool("cold_email_sending_enabled"),
  getSettingBool("coldemail_warmup_enabled"),
  getSetting("coldemail_warmup_ceiling"),
  db.coldSend.groupBy({ by: ["status"], where: { campaignId: id }, _count: true }),
  db.emailEvent.count({ where: { type: "OPEN", send: { campaignId: id } } }),
  db.emailEvent.count({ where: { type: "CLICK", send: { campaignId: id } } }),
  db.emailEvent.groupBy({ by: ["type"], where: { send: { campaignId: id } }, _count: true }),
  // LEAD-DB: list members that are dead/bounced (excluded from any (re)build).
  db.emailListMember.count({
    where: { listId: campaign.listId, contact: { emailStatus: { in: DEAD_STATUS_ENUM } } },
  }),
  db.coldSend.count({ where: { campaign: { brandId: campaign.brandId }, sentAt: { gte: startOfUtcDay() } } }),
]);
const eventCount = (t: string) => eventGroups.find((g) => g.type === t)?._count ?? 0;
const bounced = eventCount("BOUNCE") + eventCount("HARD_BOUNCE") + eventCount("SOFT_BOUNCE");
const delivered = eventCount("DELIVERED");
