import {
  SendingDomainForm,
  DomainVerificationForm,
  DomainStatusButtons,
  InboxForm,
  InboxControls,
} from "@/components/admin/coldemail/Phase3Controls";
import { SendingDomainDnsVerify } from "@/components/admin/coldemail/DnsVerify";
import { warmupStatus } from "@/lib/coldemail/warmup";
import { warmupDayIndex } from "@/lib/coldemail/compliance";

export const dynamic = "force-dynamic";

// The 2026 mandatory-NOW readiness checklist per sending domain (research §5).
function domainReadiness(d: {
  spfVerified: boolean;
  dkimVerified: boolean;
  dmarcVerified: boolean;
  dmarcPolicy: string;
  trackingDomain: string;
  trackingDomainVerified: boolean;
  oneClickUnsub: boolean;
}): { label: string; ok: boolean; hint: string }[] {
  return [
    { label: "SPF + DKIM aligned", ok: d.spfVerified && d.dkimVerified, hint: "Both configured and passing, aligned to the From domain." },
    { label: "DMARC published (min p=none)", ok: d.dmarcVerified && d.dmarcPolicy !== "NONE" ? true : d.dmarcVerified, hint: "DMARC record with a RUA reporting tag." },
    { label: "One-click unsubscribe (RFC 8058)", ok: d.oneClickUnsub, hint: "List-Unsubscribe + List-Unsubscribe-Post, honoured ≤2 days." },
    { label: "Custom tracking domain", ok: !!d.trackingDomain && d.trackingDomainVerified, hint: "Shared tracking domains are blocklisted and tank placement." },
  ];
}

export default async function ColdEmailDomains() {
  await requireArea("platform");

  const [brands, domains] = await Promise.all([
    db.brand.findMany({ orderBy: { createdAt: "asc" }, select: { id: true, name: true } }),
    db.sendingDomain.findMany({
      orderBy: { addedAt: "asc" },
      include: { brand: { select: { name: true } }, inboxes: { orderBy: { createdAt: "asc" } }, _count: { select: { inboxes: true } } },
    }),
  ]);

  const brandOptions = brands.map((b) => ({ id: b.id, label: b.name }));
  const domainOptions = domains.map((d) => ({ id: d.id, label: `${d.subdomain}.${d.domain} (${d.brand.name})` }));

  return (
