const [brands, domains, inboxMetrics] = await Promise.all([
  db.brand.findMany({ orderBy: { createdAt: "asc" }, select: { id: true, name: true } }),
  db.sendingDomain.findMany({
    orderBy: { addedAt: "asc" },
    include: { brand: { select: { name: true } }, inboxes: { orderBy: { createdAt: "asc" } }, _count: { select: { inboxes: true } } },
  }),
  // Mailbox-level lifetime rollup (from the MetricsDaily spine).
  db.metricsDaily.groupBy({
    by: ["scopeId"],
    where: { scope: "INBOX" },
    _sum: { sent: true, delivered: true, hardBounce: true, softBounce: true, replies: true, unsubscribes: true },
  }),
]);

const inboxStats = new Map(
  inboxMetrics.map((m) => [
    m.scopeId,
    {
      sent: m._sum.sent ?? 0,
      bounced: (m._sum.hardBounce ?? 0) + (m._sum.softBounce ?? 0),
      replied: m._sum.replies ?? 0,
      unsub: m._sum.unsubscribes ?? 0,
    },
  ]),
);
